-- ============================================================================
-- AsClaw 初始化数据脚本 02_data.sql
-- 职责：初始化数据（幂等，全部 INSERT IGNORE，可重复执行不产生重复数据）
-- 前置：先执行 01_schema.sql 建库建表
--
-- 执行方式：
--   1) 全新数据卷：docker compose 首次启动时自动按文件名顺序执行
--   2) 已有数据卷：docker exec -i mysql mysql -uroot -p'<密码>' \
--        --default-character-set=utf8mb4 < docker/sql/mysql/init/02_data.sql
-- ============================================================================

-- 关键：入口脚本每个文件是独立的 mysql 客户端会话，默认 latin1 会把
-- UTF-8 中文二次编码成乱码，必须先切换会话字符集再执行 INSERT
SET NAMES utf8mb4;

USE `asclaw`;

