INSERT IGNORE INTO `mcp_server`
  (`id`, `server_title`, `server_name`, `transport`, `server_type`, `compile_type`, `server_config`, `envs`, `git`, `readme`, `avatar`, `description`, `server_metadata`, `tools`, `prompts`, `resources`, `is_public`, `is_recommend`, `category_id`, `user_id`, `created_time`, `updated_time`, `cover`)
VALUES
  (2, 'Github的维基百科DeepWiKi', 'Github的维基百科DeepWiKi', 'streamable_http', 'remote', 'package', '{"mcpServers": {"deepwiki_http2": {"url": "https://mcp.deepwiki.com/mcp", "auth": null, "icon": null, "type": "streamableHttp", "headers": {}, "timeout": null, "transport": null, "description": null, "authentication": null, "sse_read_timeout": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/Github%E7%9A%84%E7%BB%B4%E5%9F%BA%E7%99%BE%E7%A7%91DeepWiKi.png', '给 GitHub 仓库配的 AI 问答百科：看结构、读文档、直接提问，一次还能跨 10 个仓库对比，读源码神器', '{"meta": null, "serverInfo": {"name": "DeepWiki", "title": null, "version": "4.0.2"}, "capabilities": {"tools": {"listChanged": true}, "logging": {}, "prompts": {"listChanged": true}, "resources": {"subscribe": false, "listChanged": true}, "completions": null, "experimental": null}, "instructions": "DeepWiki MCP provides AI-powered documentation for GitHub repositories.\\n\\nWith a user OAuth token, all devin_* tools act in one organization: without an X-Org-Id header, the first one the user joined. Not found usually means another of their orgs; send X-Org-Id: <org id> to switch.\\n\\nAvailable tools:\\n- read_wiki_structure: Get a list of documentation topics for a repository\\n- read_wiki_contents: View full documentation about a repository\\n- ask_wiki_question: Ask any question about a repository\'s codebase and get an AI-powered answer from its wiki\\n- list_wiki_repos: List the repositories that have a DeepWiki index (private mode only)\\n- generate_wiki: Generate a codebase wiki for a repository — only use when explicitly requested by the user (private mode only)\\n- devin_automation_manage: Manage Devin automations — list, get, create, update, delete, or fetch the trigger event schemas (private mode only)\\n- devin_billing_tag_manage: Manage Devin billing tags (groupings of Devin sessions for usage tracking) — list, get, create, assign sessions, look up session tags (private mode only)\\n- devin_blueprint_test: Test a candidate blueprint YAML in an authoring VM: start → run initialize → fix → run initialize again (clean VM) → run maintenance → then persist with update_environment_config (private mode only)\\n- devin_campaign_manage: Read and publish a bot\'s campaign documents (plan, readings, status) — get, update, validate (private mode only)\\n- devin_code_scan_manage: Manage Devin code scans, sometimes referred to as \'security scans\' or \'Devin Security Swarm\' — list scans, list findings, list profiles, get a profile, create a scan, remediate a finding (private mode only)\\n- devin_knowledge_manage: Manage Devin knowledge notes and suggestions — list, search, get, create, update, delete notes, view folder structure, list/view/dismiss knowledge suggestions (private mode only)\\n- devin_mcp_server_manage: Manage org MCP server installations — install (marketplace or custom), update, enable, disable, delete (private mode only)\\n- devin_oncall_manage: Devin Oncall operations — create and manage Oncall responders (alert, bug report and support request triage), get an Oncall report\'s current responder membership, page through a responder\'s open issues, and ingest a dashboard into Oncall knowledge (private mode only)\\n- devin_playbook_manage: Manage Devin playbooks — list, get, create, update, delete (private mode only)\\n- devin_review_manage: Trigger a Devin Review for a pull request, fetch the latest review status, or fetch a completed review\'s findings (private mode only)\\n- devin_schedule_manage: Manage scheduled Devin sessions — list, get, create, update, delete (private mode only)\\n- devin_session_create: Create one or more child Devin sessions (private mode only)\\n- devin_session_interact: Manage a Devin session — get status (one or many sessions, optionally with a short AI summary of each), send messages, sleep/terminate/archive/unarchive, read messages & attachments, manage tags (private mode only)\\n- devin_session_events: Inspect session events — list summaries, fetch full details, or search event contents (private mode only)\\n- devin_session_search: Search and filter Devin sessions (private mode only)\\n- devin_session_insights: Per-session cost, message counts and AI analysis (issues, action items, classification) — list, get, generate (private mode only)\\n- devin_user_list: List the organization\'s users by membership kind (direct members or IdP-group members) (private mode only)\\n- devin_list_integrations: List all native integrations and MCP servers with their status and settings URLs (private mode only)\\n- devin_find_setting: Find Devin webapp settings pages and deep-link URLs for them (private mode only)\\n", "protocolVersion": "2025-06-18"}', '[{"meta": {"fastmcp": {"tags": []}}, "name": "ask_wiki_question", "title": "Ask Wiki Question", "annotations": null, "description": "Ask any question about a GitHub repository\'s codebase and get an AI-powered answer\\ngrounded in its DeepWiki.", "inputSchema": {"type": "object", "required": ["repoName", "question"], "properties": {"question": {"type": "string", "description": "The question to ask about the repository."}, "repoName": {"anyOf": [{"type": "string"}, {"type": "array", "items": {"type": "string"}}], "description": "GitHub repository or list of repositories (max 10) in owner/repo format."}}, "additionalProperties": false}, "outputSchema": {"type": "object", "required": ["result"], "properties": {"result": {"type": "string"}}, "x-fastmcp-wrap-result": true}}, {"meta": {"fastmcp": {"tags": []}}, "name": "read_wiki_contents", "title": "Read Wiki Contents", "annotations": null, "description": "View documentation about a GitHub repository.", "inputSchema": {"type": "object", "required": ["repoName"], "properties": {"repoName": {"type": "string", "description": "GitHub repository in owner/repo format (e.g. \\"facebook/react\\")."}}, "additionalProperties": false}, "outputSchema": {"type": "object", "required": ["result"], "properties": {"result": {"type": "string"}}, "x-fastmcp-wrap-result": true}}, {"meta": {"fastmcp": {"tags": []}}, "name": "read_wiki_structure", "title": "Read Wiki Structure", "annotations": null, "description": "Get a list of documentation topics for a GitHub repository.", "inputSchema": {"type": "object", "required": ["repoName"], "properties": {"repoName": {"type": "string", "description": "GitHub repository in owner/repo format (e.g. \\"facebook/react\\")."}}, "additionalProperties": false}, "outputSchema": {"type": "object", "required": ["result"], "properties": {"result": {"type": "string"}}, "x-fastmcp-wrap-result": true}}]', NULL, NULL, 1, 1, NULL, 1, '2026-11-05 11:30:28', NULL, NULL);
INSERT IGNORE INTO `mcp_server`
  (`id`, `server_title`, `server_name`, `transport`, `server_type`, `compile_type`, `server_config`, `envs`, `git`, `readme`, `avatar`, `description`, `server_metadata`, `tools`, `prompts`, `resources`, `is_public`, `is_recommend`, `category_id`, `user_id`, `created_time`, `updated_time`, `cover`)
VALUES
  (4, '本地/云端文件处理', '本地-云端文件处理', 'stdio', 'local', 'package', '{"mcpServers": {"filesystem-demo": {"cwd": null, "env": {}, "args": ["-y", "@modelcontextprotocol/server-filesystem", "/tmp/mcp-playground"], "icon": null, "type": null, "command": "npx", "timeout": null, "transport": "stdio", "description": null, "authentication": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/%E6%96%87%E4%BB%B6%E5%A4%84%E7%90%86.png', '给 AI 划一块安全地盘：读写文件、差异编辑、目录树、通配符搜索 14 般工具，白名单沙箱内干活防越权', '{"meta": null, "serverInfo": {"name": "secure-filesystem-server", "title": null, "version": "1.0.0"}, "capabilities": {"tools": {"listChanged": true}, "logging": null, "prompts": null, "resources": null, "completions": null, "experimental": null}, "instructions": null, "protocolVersion": "2025-06-18"}', '[{"meta": null, "name": "read_file", "title": "Read File (Deprecated)", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": true, "openWorldHint": false, "idempotentHint": null, "destructiveHint": null}, "description": "Read the complete contents of a file as text. DEPRECATED: Use read_text_file instead.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["path"], "properties": {"head": {"type": "number", "description": "If provided, returns only the first N lines of the file"}, "path": {"type": "string"}, "tail": {"type": "number", "description": "If provided, returns only the last N lines of the file"}}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "string"}}, "additionalProperties": false}}, {"meta": null, "name": "read_text_file", "title": "Read Text File", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": true, "openWorldHint": false, "idempotentHint": null, "destructiveHint": null}, "description": "Read the complete contents of a file from the file system as text. Handles various text encodings and provides detailed error messages if the file cannot be read. Use this tool when you need to examine the contents of a single file. Use the \'head\' parameter to read only the first N lines of a file, or the \'tail\' parameter to read only the last N lines of a file. Operates on the file as text regardless of extension. Only works within allowed directories.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["path"], "properties": {"head": {"type": "number", "description": "If provided, returns only the first N lines of the file"}, "path": {"type": "string"}, "tail": {"type": "number", "description": "If provided, returns only the last N lines of the file"}}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "string"}}, "additionalProperties": false}}, {"meta": null, "name": "read_media_file", "title": "Read Media File", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": true, "openWorldHint": false, "idempotentHint": null, "destructiveHint": null}, "description": "Read a file and return it as a base64-encoded content block with its MIME type. Image and audio files are returned as image/audio content; any other file type is returned as an embedded resource. Only works within allowed directories.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["path"], "properties": {"path": {"type": "string"}}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "array", "items": {"anyOf": [{"type": "object", "required": ["type", "data", "mimeType"], "properties": {"data": {"type": "string"}, "type": {"enum": ["image", "audio"], "type": "string"}, "mimeType": {"type": "string"}}, "additionalProperties": false}, {"type": "object", "required": ["type", "resource"], "properties": {"type": {"type": "string", "const": "resource"}, "resource": {"type": "object", "required": ["uri", "blob"], "properties": {"uri": {"type": "string"}, "blob": {"type": "string"}, "mimeType": {"type": "string"}}, "additionalProperties": false}}, "additionalProperties": false}]}}}, "additionalProperties": false}}, {"meta": null, "name": "read_multiple_files", "title": "Read Multiple Files", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": true, "openWorldHint": false, "idempotentHint": null, "destructiveHint": null}, "description": "Read the contents of multiple files simultaneously. This is more efficient than reading files one by one when you need to analyze or compare multiple files. Each file\'s content is returned with its path as a reference. Failed reads for individual files won\'t stop the entire operation. Only works within allowed directories.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["paths"], "properties": {"paths": {"type": "array", "items": {"type": "string"}, "minItems": 1, "description": "Array of file paths to read. Each path must be a string pointing to a valid file within allowed directories."}}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "string"}}, "additionalProperties": false}}, {"meta": null, "name": "write_file", "title": "Write File", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": false, "openWorldHint": false, "idempotentHint": true, "destructiveHint": true}, "description": "Create a new file or completely overwrite an existing file with new content. Use with caution as it will overwrite existing files without warning. Handles text content with proper encoding. Only works within allowed directories.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["path", "content"], "properties": {"path": {"type": "string"}, "content": {"type": "string"}}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "string"}}, "additionalProperties": false}}, {"meta": null, "name": "edit_file", "title": "Edit File", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": false, "openWorldHint": false, "idempotentHint": false, "destructiveHint": true}, "description": "Make line-based edits to a text file. Each edit replaces exact line sequences with new content. Returns a git-style diff showing the changes made. Only works within allowed directories.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["path", "edits"], "properties": {"path": {"type": "string"}, "edits": {"type": "array", "items": {"type": "object", "required": ["oldText", "newText"], "properties": {"newText": {"type": "string", "description": "Text to replace with"}, "oldText": {"type": "string", "description": "Text to search for - must match exactly"}}}}, "dryRun": {"type": "boolean", "default": false, "description": "Preview changes using git-style diff format"}}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "string"}}, "additionalProperties": false}}, {"meta": null, "name": "create_directory", "title": "Create Directory", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": false, "openWorldHint": false, "idempotentHint": true, "destructiveHint": false}, "description": "Create a new directory or ensure a directory exists. Can create multiple nested directories in one operation. If the directory already exists, this operation will succeed silently. Perfect for setting up directory structures for projects or ensuring required paths exist. Only works within allowed directories.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["path"], "properties": {"path": {"type": "string"}}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "string"}}, "additionalProperties": false}}, {"meta": null, "name": "list_directory", "title": "List Directory", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": true, "openWorldHint": false, "idempotentHint": null, "destructiveHint": null}, "description": "Get a detailed listing of all files and directories in a specified path. Results clearly distinguish between files and directories with [FILE] and [DIR] prefixes. This tool is essential for understanding directory structure and finding specific files within a directory. Only works within allowed directories.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["path"], "properties": {"path": {"type": "string"}}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "string"}}, "additionalProperties": false}}, {"meta": null, "name": "list_directory_with_sizes", "title": "List Directory with Sizes", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": true, "openWorldHint": false, "idempotentHint": null, "destructiveHint": null}, "description": "Get a detailed listing of all files and directories in a specified path, including sizes. Results clearly distinguish between files and directories with [FILE] and [DIR] prefixes. This tool is useful for understanding directory structure and finding specific files within a directory. Only works within allowed directories.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["path"], "properties": {"path": {"type": "string"}, "sortBy": {"enum": ["name", "size"], "type": "string", "default": "name", "description": "Sort entries by name or size"}}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "string"}}, "additionalProperties": false}}, {"meta": null, "name": "directory_tree", "title": "Directory Tree", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": true, "openWorldHint": false, "idempotentHint": null, "destructiveHint": null}, "description": "Get a recursive tree view of files and directories as a JSON structure. Each entry includes \'name\', \'type\' (file/directory), and \'children\' for directories. Files have no children array, while directories always have a children array (which may be empty). The output is formatted with 2-space indentation for readability. Only works within allowed directories.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["path"], "properties": {"path": {"type": "string"}, "excludePatterns": {"type": "array", "items": {"type": "string"}, "default": []}}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "string"}}, "additionalProperties": false}}, {"meta": null, "name": "move_file", "title": "Move File", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": false, "openWorldHint": false, "idempotentHint": false, "destructiveHint": true}, "description": "Move or rename files and directories. Can move files between directories and rename them in a single operation. If the destination exists, the operation will fail. Works across different directories and can be used for simple renaming within the same directory. Both source and destination must be within allowed directories.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["source", "destination"], "properties": {"source": {"type": "string"}, "destination": {"type": "string"}}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "string"}}, "additionalProperties": false}}, {"meta": null, "name": "search_files", "title": "Search Files", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": true, "openWorldHint": false, "idempotentHint": null, "destructiveHint": null}, "description": "Recursively search for files and directories matching a pattern. The patterns should be glob-style patterns that match paths relative to the working directory. Use pattern like \'*.ext\' to match files in current directory, and \'**/*.ext\' to match files in all subdirectories. Returns full paths to all matching items. Great for finding files when you don\'t know their exact location. Only searches within allowed directories.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["path", "pattern"], "properties": {"path": {"type": "string"}, "pattern": {"type": "string"}, "excludePatterns": {"type": "array", "items": {"type": "string"}, "default": []}}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "string"}}, "additionalProperties": false}}, {"meta": null, "name": "get_file_info", "title": "Get File Info", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": true, "openWorldHint": false, "idempotentHint": null, "destructiveHint": null}, "description": "Retrieve detailed metadata about a file or directory. Returns comprehensive information including size, creation time, last modified time, permissions, and type. This tool is perfect for understanding file characteristics without reading the actual content. Only works within allowed directories.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["path"], "properties": {"path": {"type": "string"}}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "string"}}, "additionalProperties": false}}, {"meta": null, "name": "list_allowed_directories", "title": "List Allowed Directories", "execution": {"taskSupport": "forbidden"}, "annotations": {"title": null, "readOnlyHint": true, "openWorldHint": false, "idempotentHint": null, "destructiveHint": null}, "description": "Returns the list of directories that this server is allowed to access. Subdirectories within these allowed directories are also accessible. Use this to understand which directories and their nested paths are available before trying to access files.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "properties": {}}, "outputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["content"], "properties": {"content": {"type": "string"}}, "additionalProperties": false}}]', NULL, NULL, 1, 1, NULL, 1, '2026-11-05 13:13:21', '2026-11-10 17:51:25', NULL);
INSERT IGNORE INTO `mcp_server`
  (`id`, `server_title`, `server_name`, `transport`, `server_type`, `compile_type`, `server_config`, `envs`, `git`, `readme`, `avatar`, `description`, `server_metadata`, `tools`, `prompts`, `resources`, `is_public`, `is_recommend`, `category_id`, `user_id`, `created_time`, `updated_time`, `cover`)
VALUES
  (5, 'Context7 Docs', 'Context7 Docs', 'streamable_http', 'remote', 'package', '{"mcpServers": {"context7_docs": {"url": "https://mcp.context7.com/mcp", "auth": null, "icon": null, "type": "streamableHttp", "headers": {}, "timeout": null, "transport": null, "description": null, "authentication": null, "sse_read_timeout": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/Context7.png', 'Context7 是一个实时代码文档检索服务，用于获取最新版本的库 API 和代码示例，适合在 AI 编程时解决文档过时、API 幻觉或版本不匹配的问题。', '{"meta": null, "serverInfo": {"name": "Context7", "icons": [{"src": "https://context7.com/context7-icon-green.svg", "sizes": ["any"], "mimeType": "image/svg+xml"}, {"src": "https://context7.com/context7-icon-green.png", "sizes": ["512x512"], "mimeType": "image/png"}], "title": "Context7", "version": "4.5.0", "websiteUrl": "https://context7.com", "description": "Context7 provides up-to-date documentation and code examples for libraries and frameworks."}, "capabilities": {"tools": {"listChanged": false}, "logging": null, "prompts": {"listChanged": false}, "resources": {"subscribe": false, "listChanged": false}, "completions": null, "experimental": null}, "instructions": "Use this server to fetch current documentation whenever the user asks about a library, framework, SDK, API, CLI tool, or cloud service — even well-known ones like React, Next.js, Prisma, Express, Tailwind, Django, or Spring Boot. This includes API syntax, configuration, version migration, porting code between libraries, platforms, or SQL dialects, library-specific debugging, setup instructions, and CLI tool usage. Use even when you think you know the answer — your training data may not reflect recent changes. Prefer this over web search for library docs.\\n\\nDo not use for: refactoring, debugging, or reviewing code that does not depend on a library or platform API, or general programming concepts.", "protocolVersion": "2025-06-18"}', '[{"meta": null, "name": "resolve-library-id", "title": "Resolve Context7 Library ID", "annotations": {"title": null, "readOnlyHint": true, "openWorldHint": true, "idempotentHint": true, "destructiveHint": false}, "description": "Resolves a package/product name to a Context7-compatible library ID and returns matching libraries.\\n\\nYou MUST call this function before \'Query Documentation\' tool to obtain a valid Context7-compatible library ID UNLESS the user explicitly provides a library ID in the format \'/org/project\' or \'/org/project/version\' in their query.\\n\\nEach result includes:\\n- Library ID: Context7-compatible identifier (format: /org/project)\\n- Name: Library or package name\\n- Description: Short summary\\n- Code Snippets: Number of available code examples\\n- Source Reputation: Authority indicator (High, Medium, Low, or Unknown)\\n- Benchmark Score: Quality indicator (100 is the highest score)\\n- Versions: List of versions if available. Use one of those versions if the user provides a version in their query. The format of the version is /org/project/version.\\n\\nFor best results, select libraries based on name match, source reputation, snippet coverage, benchmark score, and relevance to your use case.\\n\\nSelection Process:\\n1. Analyze the query to understand what library/package the user is looking for\\n2. Return the most relevant match based on:\\n- Name similarity to the query (exact matches prioritized)\\n- Description relevance to the query\'s intent\\n- Documentation coverage (prioritize libraries with higher Code Snippet counts)\\n- Source reputation (consider libraries with High or Medium reputation more authoritative)\\n- Benchmark Score: Quality indicator (100 is the highest score)\\n\\nResponse Format:\\n- Return the selected library ID in a clearly marked section\\n- Provide a brief explanation for why this library was chosen\\n- If multiple good matches exist, acknowledge this but proceed with the most relevant one\\n- If no good matches exist, clearly state this and suggest query refinements\\n\\nFor ambiguous queries, request clarification before proceeding with a best-guess match.\\n\\nIMPORTANT: Do not call this tool more than 3 times per question. If you cannot find what you need after 3 calls, use the best result you have.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["query", "libraryName"], "properties": {"query": {"type": "string", "description": "What to look up in the library\'s documentation. This is used to rank library results by relevance to what the user is trying to accomplish. The query is sent to the Context7 API for processing. Do not include any sensitive or confidential information such as API keys, passwords, credentials, personal data, or proprietary code in your query."}, "libraryName": {"type": "string", "description": "Library name to search for and retrieve a Context7-compatible library ID. Use the official library name with proper punctuation — e.g., \'Next.js\' instead of \'nextjs\', \'Customer.io\' instead of \'customerio\', \'Three.js\' instead of \'threejs\'."}}}, "outputSchema": null}, {"meta": null, "name": "query-docs", "title": "Query Documentation", "annotations": {"title": null, "readOnlyHint": true, "openWorldHint": true, "idempotentHint": true, "destructiveHint": false}, "description": "Retrieves and queries up-to-date documentation and code examples from Context7 for any programming library or framework.\\n\\nYou must call \'Resolve Context7 Library ID\' tool first to obtain the exact Context7-compatible library ID required to use this tool, UNLESS the user explicitly provides a library ID in the format \'/org/project\' or \'/org/project/version\' in their query.\\n\\nDo not call this tool more than 3 times per question.\\n\\nIf you know the programming language the user is working in, pass it as `language` so the results match their setup.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["libraryId", "query"], "properties": {"query": {"type": "string", "description": "What to look up in the library\'s documentation, scoped to a single concept. Be specific and include relevant details, but keep each query to one topic — if the user\'s question spans multiple distinct concepts, make a separate call per concept instead of combining them, unless the question is about how the concepts interact. Good: \'How to set up authentication with JWT in Express.js\' or \'React useEffect cleanup function examples\'. Bad (too vague): \'auth\' or \'hooks\'. Bad (too broad): \'routing and auth and caching in Next.js\'. The query is sent to the Context7 API for processing. Do not include any sensitive or confidential information such as API keys, passwords, credentials, personal data, or proprietary code in your query."}, "language": {"type": "string", "description": "Programming language the user is writing code in, such as \'Python\', \'TypeScript\', \'Go\', or \'C#\'. Ranks code examples in that language first. Leave it out when the language is unknown or does not apply."}, "libraryId": {"type": "string", "description": "Exact Context7-compatible library ID (e.g., \'/mongodb/docs\', \'/vercel/next.js\', \'/supabase/supabase\', \'/vercel/next.js/v16.2.9\') retrieved from \'resolve-library-id\' or directly from user query in the format \'/org/project\' or \'/org/project/version\'."}}}, "outputSchema": null}]', NULL, NULL, 1, 1, NULL, 1, '2026-11-05 13:23:20', NULL, NULL);
INSERT IGNORE INTO `mcp_server`
  (`id`, `server_title`, `server_name`, `transport`, `server_type`, `compile_type`, `server_config`, `envs`, `git`, `readme`, `avatar`, `description`, `server_metadata`, `tools`, `prompts`, `resources`, `is_public`, `is_recommend`, `category_id`, `user_id`, `created_time`, `updated_time`, `cover`)
VALUES
  (6, 'AMap MCP 2高德地图', 'AMap MCP 2高德地图', 'streamable_http', 'remote', 'package', '{"mcpServers": {"amap_mcp_2": {"url": "https://mcp.amap.com/mcp?key=***", "auth": null, "icon": null, "type": "streamableHttp", "headers": {}, "timeout": null, "transport": null, "description": null, "authentication": null, "sse_read_timeout": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/%E9%AB%98%E5%BE%B7%E5%9C%B0%E5%9B%BE.png', '高德官方出行能力：查地点、搜周边、算路线、测距离、看天气，行程可生成地图链接，一键唤起导航与打车。', '{"meta": null, "serverInfo": {"name": "amap-sse-server", "title": null, "version": "1.0.0"}, "capabilities": {"tools": {"listChanged": false}, "logging": {}, "prompts": null, "resources": null, "completions": null, "experimental": null}, "instructions": null, "protocolVersion": "2025-03-26"}', '[{"meta": null, "name": "maps_direction_bicycling", "title": null, "annotations": null, "description": "骑行路径规划用于规划骑行通勤方案，规划时会考虑天桥、单行线、封路等情况。最大支持 500km 的骑行路线规划", "inputSchema": {"type": "object", "required": ["origin", "destination"], "properties": {"origin": {"type": "string", "description": "出发点经纬度，坐标格式为：经度，纬度"}, "destination": {"type": "string", "description": "目的地经纬度，坐标格式为：经度，纬度"}}}, "outputSchema": null}, {"meta": null, "name": "maps_direction_driving", "title": null, "annotations": null, "description": "驾车路径规划 API 可以根据用户起终点经纬度坐标规划以小客车、轿车通勤出行的方案，并且返回通勤方案的数据。", "inputSchema": {"type": "object", "required": ["origin", "destination"], "properties": {"origin": {"type": "string", "description": "出发点经纬度，坐标格式为：经度，纬度"}, "destination": {"type": "string", "description": "目的地经纬度，坐标格式为：经度，纬度"}}}, "outputSchema": null}, {"meta": null, "name": "maps_direction_transit_integrated", "title": null, "annotations": null, "description": "根据用户起终点经纬度坐标规划综合各类公共（火车、公交、地铁）交通方式的通勤方案，并且返回通勤方案的数据，跨城场景下必须传起点城市与终点城市", "inputSchema": {"type": "object", "required": ["origin", "destination", "city", "cityd"], "properties": {"city": {"type": "string", "description": "公共交通规划起点城市"}, "cityd": {"type": "string", "description": "公共交通规划终点城市"}, "origin": {"type": "string", "description": "出发点经纬度，坐标格式为：经度，纬度"}, "destination": {"type": "string", "description": "目的地经纬度，坐标格式为：经度，纬度"}}}, "outputSchema": null}, {"meta": null, "name": "maps_direction_walking", "title": null, "annotations": null, "description": "根据输入起点终点经纬度坐标规划100km 以内的步行通勤方案，并且返回通勤方案的数据", "inputSchema": {"type": "object", "required": ["origin", "destination"], "properties": {"origin": {"type": "string", "description": "出发点经度，纬度，坐标格式为：经度，纬度"}, "destination": {"type": "string", "description": "目的地经度，纬度，坐标格式为：经度，纬度"}}}, "outputSchema": null}, {"meta": null, "name": "maps_distance", "title": null, "annotations": null, "description": "测量两个经纬度坐标之间的距离,支持驾车、步行以及球面距离测量", "inputSchema": {"type": "object", "required": ["origins", "destination"], "properties": {"type": {"type": "string", "description": "距离测量类型,1代表驾车距离测量，0代表直线距离测量，3步行距离测量"}, "origins": {"type": "string", "description": "起点经度，纬度，可以传多个坐标，使用竖线隔离，比如120,30|120,31，坐标格式为：经度，纬度"}, "destination": {"type": "string", "description": "终点经度，纬度，坐标格式为：经度，纬度"}}}, "outputSchema": null}, {"meta": null, "name": "maps_geo", "title": null, "annotations": null, "description": "将详细的结构化地址转换为经纬度坐标。支持对地标性名胜景区、建筑物名称解析为经纬度坐标", "inputSchema": {"type": "object", "required": ["address"], "properties": {"city": {"type": "string", "description": "指定查询的城市"}, "address": {"type": "string", "description": "待解析的结构化地址信息"}}}, "outputSchema": null}, {"meta": null, "name": "maps_regeocode", "title": null, "annotations": null, "description": "将一个高德经纬度坐标转换为行政区划地址信息", "inputSchema": {"type": "object", "required": ["location"], "properties": {"location": {"type": "string", "description": "经纬度"}}}, "outputSchema": null}, {"meta": null, "name": "maps_ip_location", "title": null, "annotations": null, "description": "IP 定位根据用户输入的 IP 地址，定位 IP 的所在位置", "inputSchema": {"type": "object", "required": ["ip"], "properties": {"ip": {"type": "string", "description": "IP地址"}}}, "outputSchema": null}, {"meta": null, "name": "maps_schema_personal_map", "title": null, "annotations": null, "description": "用于行程规划结果在高德地图展示。将行程规划位置点按照行程顺序填入lineList，返回结果为高德地图打开的URI链接，该结果不需总结，直接返回！", "inputSchema": {"type": "object", "required": ["orgName", "lineList"], "properties": {"orgName": {"type": "string", "description": "行程规划地图小程序名称"}, "lineList": {"type": "array", "items": {"type": "object", "required": ["title", "pointInfoList"], "properties": {"title": {"type": "string", "description": "行程名称描述（按行程顺序）"}, "pointInfoList": {"type": "array", "items": {"type": "object", "required": ["name", "lon", "lat", "poiId"], "properties": {"lat": {"type": "number", "description": "行程目标位置点纬度"}, "lon": {"type": "number", "description": "行程目标位置点经度"}, "name": {"type": "string", "description": "行程目标位置点名称"}, "poiId": {"type": "string", "description": "行程目标位置点POIID"}}}, "description": "行程目标位置点描述"}}}, "description": "行程列表"}}}, "outputSchema": null}, {"meta": null, "name": "maps_around_search", "title": null, "annotations": null, "description": "周边搜，根据用户传入关键词以及坐标location，搜索出radius半径范围的POI", "inputSchema": {"type": "object", "required": ["keywords", "location"], "properties": {"radius": {"type": "string", "description": "搜索半径"}, "keywords": {"type": "string", "description": "搜索关键词"}, "location": {"type": "string", "description": "中心点经度纬度"}, "strategy": {"type": "integer", "default": 0, "description": "召回策略，0=默认召回策略，1=优先召回扫街榜POI"}}}, "outputSchema": null}, {"meta": null, "name": "maps_search_detail", "title": null, "annotations": null, "description": "查询关键词搜或者周边搜获取到的POI ID的详细信息", "inputSchema": {"type": "object", "required": ["id"], "properties": {"id": {"type": "string", "description": "关键词搜或者周边搜获取到的POI ID"}}}, "outputSchema": null}, {"meta": null, "name": "maps_text_search", "title": null, "annotations": null, "description": "关键字搜索 API 根据用户输入的关键字进行 POI 搜索，并返回相关的信息", "inputSchema": {"type": "object", "required": ["keywords"], "properties": {"city": {"type": "string", "description": "查询城市"}, "keywords": {"type": "string", "description": "查询关键字"}, "citylimit": {"type": "boolean", "default": false, "description": "是否限制城市范围内搜索，默认不限制"}}}, "outputSchema": null}, {"meta": null, "name": "maps_schema_navi", "title": null, "annotations": null, "description": " Schema唤醒客户端-导航页面，用于根据用户输入终点信息，返回一个拼装好的客户端唤醒URI，用户点击该URI即可唤起对应的客户端APP。唤起客户端后，会自动跳转到导航页面。", "inputSchema": {"type": "object", "required": ["lon", "lat"], "properties": {"lat": {"type": "string", "description": "终点纬度"}, "lon": {"type": "string", "description": "终点经度"}}}, "outputSchema": null}, {"meta": null, "name": "maps_schema_take_taxi", "title": null, "annotations": null, "description": "根据用户输入的起点和终点信息，返回一个拼装好的客户端唤醒URI，直接唤起高德地图进行打车。直接展示生成的链接，不需要总结", "inputSchema": {"type": "object", "required": ["dlon", "dlat", "dname"], "properties": {"dlat": {"type": "string", "description": "终点纬度"}, "dlon": {"type": "string", "description": "终点经度"}, "slat": {"type": "string", "description": "起点纬度"}, "slon": {"type": "string", "description": "起点经度"}, "dname": {"type": "string", "description": "终点名称"}, "sname": {"type": "string", "description": "起点名称"}}}, "outputSchema": null}, {"meta": null, "name": "maps_weather", "title": null, "annotations": null, "description": "根据城市名称或者标准adcode查询指定城市的天气", "inputSchema": {"type": "object", "required": ["city"], "properties": {"city": {"type": "string", "description": "城市名称或者adcode"}}}, "outputSchema": null}]', NULL, NULL, 1, 1, NULL, 1, '2026-11-05 14:04:36', '2026-11-10 14:52:41', '');
INSERT IGNORE INTO `mcp_server`
  (`id`, `server_title`, `server_name`, `transport`, `server_type`, `compile_type`, `server_config`, `envs`, `git`, `readme`, `avatar`, `description`, `server_metadata`, `tools`, `prompts`, `resources`, `is_public`, `is_recommend`, `category_id`, `user_id`, `created_time`, `updated_time`, `cover`)
VALUES
  (8, '12306-MCP车票查询工具', '12306-mcp', 'stdio', 'local', 'package', '{"mcpServers": {"12306-mcp": {"cwd": null, "env": {}, "args": ["-y", "12306-mcp"], "icon": null, "type": null, "command": "npx", "timeout": null, "transport": "stdio", "description": null, "authentication": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/12306.png', '火车出行规划能力包：查余票、对时刻、看经停、算中转换乘，免费无需注册，一键给出候补建议', '{"meta": null, "serverInfo": {"name": "12306-mcp", "title": null, "version": "0.3.10"}, "capabilities": {"tools": {"listChanged": true}, "logging": null, "prompts": null, "resources": {"subscribe": null, "listChanged": true}, "completions": null, "experimental": null}, "instructions": "该服务主要用于帮助用户查询12306的车票信息、特定列车的经停站信息以及相关的车站信息。请仔细理解用户的意图，并按以下指引选择合适的接口：\\n\\n**原则：**\\n*   **必要时追问**：如果用户信息不足以调用接口，请向用户追问缺失的信息。\\n*   **尽量精确需求**：尽量利用筛选功能筛选用户需要的车票信息，从而简短上下文长度。\\n\\n请根据上述指引选择接口。", "protocolVersion": "2025-06-18"}', '[{"meta": null, "name": "get-current-date", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "获取当前日期，以上海时区（Asia/Shanghai, UTC+8）为准，返回格式为 \\"yyyy-MM-dd\\"。主要用于解析用户提到的相对日期（如“明天”、“下周三”），提供准确的日期输入。", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "properties": {}}, "outputSchema": null}, {"meta": null, "name": "get-stations-code-in-city", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "通过中文城市名查询该城市 **所有** 火车站的名称及其对应的 `station_code`，结果是一个包含多个车站信息的列表。", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["city"], "properties": {"city": {"type": "string", "description": "中文城市名称，例如：\\"北京\\", \\"上海\\""}}, "additionalProperties": false}, "outputSchema": null}, {"meta": null, "name": "get-station-code-of-citys", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "通过中文城市名查询代表该城市的 `station_code`。", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["citys"], "properties": {"citys": {"type": "string", "description": "要查询的城市，比如\\"北京\\"。若要查询多个城市，请用|分割，比如\\"北京|上海\\"。"}}, "additionalProperties": false}, "outputSchema": null}, {"meta": null, "name": "get-station-code-by-names", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "通过具体的中文车站名查询其 `station_code` 和车站名。", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["stationNames"], "properties": {"stationNames": {"type": "string", "description": "具体的中文车站名称，例如：\\"北京南\\", \\"上海虹桥\\"。若要查询多个站点，请用|分割，比如\\"北京南|上海虹桥\\"。"}}, "additionalProperties": false}, "outputSchema": null}, {"meta": null, "name": "get-station-by-telecode", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "通过车站的 `station_telecode` 查询车站的详细信息，包括名称、拼音、所属城市等。此接口主要用于在已知 `telecode` 的情况下获取更完整的车站数据，或用于特殊查询及调试目的。一般用户对话流程中较少直接触发。", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["stationTelecode"], "properties": {"stationTelecode": {"type": "string", "description": "车站的 `station_telecode` (3位字母编码)"}}, "additionalProperties": false}, "outputSchema": null}, {"meta": null, "name": "get-tickets", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "查询12306余票信息。", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["date", "fromStation", "toStation"], "properties": {"date": {"type": "string", "maxLength": 10, "minLength": 10, "description": "查询日期，格式为 \\"yyyy-MM-dd\\"。如果用户提供的是相对日期（如“明天”），请务必先调用 `get-current-date` 接口获取当前日期，并计算出目标日期。"}, "format": {"type": "string", "default": "text", "pattern": "^(text|csv|json)$", "description": "返回结果格式，默认为text，建议使用text与csv。可选标志：[text, csv, json]"}, "sortFlag": {"type": "string", "default": "", "description": "排序方式，默认为空，即不排序。仅支持单一标识。可选标志：[startTime(出发时间从早到晚), arriveTime(抵达时间从早到晚), duration(历时从短到长)]"}, "toStation": {"type": "string", "description": "到达地的中文名或站点的 `station_code`（可通过 `get-station-code-by-names` 或 `get-station-code-of-citys` 接口查询得到）"}, "limitedNum": {"type": "number", "default": 0, "minimum": 0, "description": "返回的余票数量限制，默认为0，即不限制。"}, "fromStation": {"type": "string", "description": "出发地的中文名或站点的 `station_code`（可通过 `get-station-code-by-names` 或 `get-station-code-of-citys` 接口查询得到）"}, "sortReverse": {"type": "boolean", "default": false, "description": "是否逆向排序结果，默认为false。仅在设置了sortFlag时生效。"}, "latestStartTime": {"type": "number", "default": 24, "maximum": 24, "minimum": 0, "description": "最迟出发时间（0-24），默认为24。"}, "trainFilterFlags": {"type": "string", "default": "", "pattern": "^[GDZTKOFS]*$", "maxLength": 8, "description": "车次筛选条件，默认为空，即不筛选。支持多个标志同时筛选。例如用户说“高铁票”，则应使用 \\"G\\"。可选标志：[G(高铁/城际),D(动车),Z(直达特快),T(特快),K(快速),O(其他),F(复兴号),S(智能动车组)]"}, "earliestStartTime": {"type": "number", "default": 0, "maximum": 24, "minimum": 0, "description": "最早出发时间（0-24），默认为0。"}}, "additionalProperties": false}, "outputSchema": null}, {"meta": null, "name": "get-interline-tickets", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "查询12306中转余票信息。尚且只支持查询前十条。", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["date", "fromStation", "toStation"], "properties": {"date": {"type": "string", "maxLength": 10, "minLength": 10, "description": "查询日期，格式为 \\"yyyy-MM-dd\\"。如果用户提供的是相对日期（如“明天”），请务必先调用 `get-current-date` 接口获取当前日期，并计算出目标日期。"}, "format": {"type": "string", "default": "text", "pattern": "^(text|json)$", "description": "返回结果格式，默认为text，建议使用text。可选标志：[text, json]"}, "showWZ": {"type": "boolean", "default": false, "description": "是否显示无座车，默认不显示无座车。"}, "sortFlag": {"type": "string", "default": "", "description": "排序方式，默认为空，即不排序。仅支持单一标识。可选标志：[startTime(出发时间从早到晚), arriveTime(抵达时间从早到晚), duration(历时从短到长)]"}, "toStation": {"type": "string", "description": "到达地的中文名或站点的 `station_code`（可通过 `get-station-code-by-names` 或 `get-station-code-of-citys` 接口查询得到）"}, "limitedNum": {"type": "number", "default": 10, "minimum": 1, "description": "返回的中转余票数量限制，默认为10。"}, "fromStation": {"type": "string", "description": "出发地的中文名或站点的 `station_code`（可通过 `get-station-code-by-names` 或 `get-station-code-of-citys` 接口查询得到）"}, "sortReverse": {"type": "boolean", "default": false, "description": "是否逆向排序结果，默认为false。仅在设置了sortFlag时生效。"}, "middleStation": {"type": "string", "default": "", "description": "中转地的中文或站点的 `station_code`（可通过 `get-station-code-by-names` 或 `get-station-code-of-citys` 接口查询得到）。该参数可选。"}, "latestStartTime": {"type": "number", "default": 24, "maximum": 24, "minimum": 0, "description": "最迟出发时间（0-24），默认为24。"}, "trainFilterFlags": {"type": "string", "default": "", "pattern": "^[GDZTKOFS]*$", "maxLength": 8, "description": "车次筛选条件，默认为空。从以下标志中选取多个条件组合[G(高铁/城际),D(动车),Z(直达特快),T(特快),K(快速),O(其他),F(复兴号),S(智能动车组)]"}, "earliestStartTime": {"type": "number", "default": 0, "maximum": 24, "minimum": 0, "description": "最早出发时间（0-24），默认为0。"}}, "additionalProperties": false}, "outputSchema": null}, {"meta": null, "name": "get-train-route-stations", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "查询特定列车车次在指定区间内的途径车站、到站时间、出发时间及停留时间等详细经停信息。当用户询问某趟具体列车的经停站时使用此接口。", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["trainCode", "departDate"], "properties": {"format": {"type": "string", "default": "text", "pattern": "^(text|json)$", "description": "返回结果格式，默认为text，建议使用text。可选标志：[text, json]"}, "trainCode": {"type": "string", "description": "要查询的车次 `train_code`，例如\\"G1033\\"。"}, "departDate": {"type": "string", "maxLength": 10, "minLength": 10, "description": "列车出发的日期 (格式: yyyy-MM-dd)。如果用户提供的是相对日期，请务必先调用 `get-current-date` 解析。"}}, "additionalProperties": false}, "outputSchema": null}]', NULL, '[{"uri": "data://all-stations", "meta": null, "name": "stations", "size": null, "title": null, "mimeType": null, "annotations": null, "description": null}]', 1, 0, NULL, 1, '2026-11-10 17:45:47', '2026-11-10 17:51:24', 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/12306.png');
INSERT IGNORE INTO `mcp_server`
  (`id`, `server_title`, `server_name`, `transport`, `server_type`, `compile_type`, `server_config`, `envs`, `git`, `readme`, `avatar`, `description`, `server_metadata`, `tools`, `prompts`, `resources`, `is_public`, `is_recommend`, `category_id`, `user_id`, `created_time`, `updated_time`, `cover`)
VALUES
  (9, '必应中文搜索 MCP 服务器', 'bing-search', 'stdio', 'local', 'package', '{"mcpServers": {"bing-search": {"cwd": null, "env": {}, "args": ["-y", "bing-cn-mcp"], "icon": null, "type": null, "command": "npx", "timeout": null, "transport": "stdio", "description": null, "authentication": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/biyingsearch.png', '必应中文搜索服务器 MCP 将 Bing 联网检索封装成标准工具，供 AI Agent 调用，返回中文网页、新闻与图片的标题、链接和摘要。', '{"meta": null, "serverInfo": {"name": "bing-cn-search", "title": null, "version": "1.0.0"}, "capabilities": {"tools": {"listChanged": true}, "logging": null, "prompts": null, "resources": null, "completions": null, "experimental": null}, "instructions": null, "protocolVersion": "2025-06-18"}', '[{"meta": null, "name": "bing_search", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "使用必应中文搜索引擎搜索信息。返回搜索结果包括标题、链接和摘要。", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["query"], "properties": {"count": {"type": "number", "default": 10, "maximum": 50, "minimum": 1, "description": "返回结果数量，默认10条，最多50条"}, "query": {"type": "string", "minLength": 1, "description": "搜索关键词或查询语句"}, "offset": {"type": "number", "default": 0, "minimum": 0, "description": "结果偏移量，用于分页，默认0"}}, "additionalProperties": false}, "outputSchema": null}, {"meta": null, "name": "crawl_webpage", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "根据搜索结果的UUID抓取网页内容。支持批量抓取多个网页。会自动过滤黑名单中的网站(如知乎、小红书等)。", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["uuids", "urlMap"], "properties": {"uuids": {"type": "array", "items": {"type": "string"}, "minItems": 1, "description": "搜索结果的UUID列表，可以是单个或多个UUID"}, "urlMap": {"type": "object", "description": "UUID到URL的映射对象，格式: {\\"uuid1\\": \\"url1\\", \\"uuid2\\": \\"url2\\"}", "additionalProperties": {"type": "string"}}}, "additionalProperties": false}, "outputSchema": null}]', NULL, NULL, 1, 0, NULL, 1, '2026-11-10 17:55:09', '2026-11-10 17:56:37', NULL);
INSERT IGNORE INTO `mcp_server`
  (`id`, `server_title`, `server_name`, `transport`, `server_type`, `compile_type`, `server_config`, `envs`, `git`, `readme`, `avatar`, `description`, `server_metadata`, `tools`, `prompts`, `resources`, `is_public`, `is_recommend`, `category_id`, `user_id`, `created_time`, `updated_time`, `cover`)
VALUES
  (10, 'Arxiv 论文小助手', 'arxiv-paper-mcp', 'stdio', 'local', 'package', '{"mcpServers": {"arxiv-paper-mcp": {"cwd": null, "env": {}, "args": ["-y", "@langgpt/arxiv-paper-mcp@latest"], "icon": null, "type": null, "command": "npx", "timeout": null, "transport": "stdio", "description": null, "authentication": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/Arxiv.png', '一个基于 arXiv 的论文检索与内容解析工具。支持 Model Context Protocol (MCP) 标准，提供论文搜索、PDF链接获取和内容解析功能。', '{"meta": null, "serverInfo": {"name": "arxiv-paper-mcp", "title": null, "version": "1.1.0"}, "capabilities": {"tools": {"listChanged": null}, "logging": null, "prompts": null, "resources": null, "completions": null, "experimental": null}, "instructions": null, "protocolVersion": "2024-11-05"}', '[{"meta": null, "name": "search_arxiv", "title": null, "annotations": null, "description": "搜索 arXiv 论文", "inputSchema": {"type": "object", "required": ["query"], "properties": {"query": {"type": "string", "description": "搜索英文关键词"}, "maxResults": {"type": "number", "default": 5, "description": "最大结果数量"}}}, "outputSchema": null}, {"meta": null, "name": "get_recent_ai_papers", "title": null, "annotations": null, "description": "获取 arXiv AI 领域最新论文（cs.AI/recent）", "inputSchema": {"type": "object", "required": [], "properties": {}}, "outputSchema": null}, {"meta": null, "name": "get_arxiv_pdf_url", "title": null, "annotations": null, "description": "获取 arXiv PDF 下载链接", "inputSchema": {"type": "object", "required": ["input"], "properties": {"input": {"type": "string", "description": "arXiv 论文URL（如：http://arxiv.org/abs/2403.15137v1）或 arXiv ID（如：2403.15137v1）"}}}, "outputSchema": null}, {"meta": null, "name": "parse_paper_content", "title": null, "annotations": null, "description": "解析论文内容（优先使用 HTML 版本，回退到 PDF）", "inputSchema": {"type": "object", "required": ["input"], "properties": {"input": {"type": "string", "description": "arXiv 论文URL或 arXiv ID"}, "paperInfo": {"type": "object", "properties": {"title": {"type": "string"}, "authors": {"type": "array"}, "summary": {"type": "string"}, "published": {"type": "string"}}, "description": "论文信息（可选，用于添加论文元数据）"}}}, "outputSchema": null}]', NULL, NULL, 1, 0, NULL, 1, '2026-11-10 18:06:02', '2026-11-10 18:07:55', NULL);
INSERT IGNORE INTO `mcp_server`
  (`id`, `server_title`, `server_name`, `transport`, `server_type`, `compile_type`, `server_config`, `envs`, `git`, `readme`, `avatar`, `description`, `server_metadata`, `tools`, `prompts`, `resources`, `is_public`, `is_recommend`, `category_id`, `user_id`, `created_time`, `updated_time`, `cover`)
VALUES
  (11, '景点智能推荐', 'SmartPoi', 'stdio', 'local', 'package', '{"mcpServers": {"SmartPoi": {"cwd": null, "env": {}, "args": ["mcp-poi-smart-recommend==5.0.2"], "icon": null, "type": null, "command": "uvx", "timeout": null, "transport": "stdio", "description": null, "authentication": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/%E6%97%85%E6%B8%B8.png', '以景点推荐为核心的 6 合 1 智能推荐服务，覆盖从「想去哪玩」到「怎么去」的全流程。结合飞猪旅行门票数据与高德地图位置服务，提供 AI 推荐、结构化搜索、周边发现、天气预报、交通规划等能力。', '{"meta": null, "serverInfo": {"name": "poi-smart-recommend", "title": null, "version": ""}, "capabilities": {"tools": {"listChanged": false}, "logging": null, "prompts": {"listChanged": false}, "resources": {"subscribe": false, "listChanged": false}, "completions": null, "experimental": null}, "instructions": null, "protocolVersion": "2025-06-18"}', '[{"meta": null, "name": "recommend_poi", "title": null, "annotations": null, "description": "景点智能推荐：按自然语言需求查找景点门票。如\'三亚适合亲子的海边景点\'\'杭州5A景区\'。数据来源：途牛旅行。", "inputSchema": {"type": "object", "title": "recommend_poiArguments", "required": ["query"], "properties": {"query": {"type": "string", "title": "Query", "description": "景点推荐描述，自然语言，如\'三亚适合亲子的海边景点\'\'杭州5A景区推荐\'\'国庆去哪里人少景美\'"}}}, "outputSchema": {"type": "object", "title": "recommend_poiOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_poi", "title": null, "annotations": null, "description": "景点门票搜索：按景点名查询，返回门票价格与票种。数据来源：途牛旅行。", "inputSchema": {"type": "object", "title": "search_poiArguments", "required": ["cityName"], "properties": {"keyword": {"type": "string", "title": "Keyword", "default": "", "description": "景点名称关键词，如故宫、长城、迪士尼"}, "category": {"type": "string", "title": "Category", "default": "", "description": "景点类型，如自然风光、主题乐园、人文古迹"}, "cityName": {"type": "string", "title": "Cityname", "description": "城市名，如杭州、西安"}, "poiLevel": {"type": "integer", "title": "Poilevel", "default": 0, "description": "景点等级1-5（5为5A），0表示不限"}}}, "outputSchema": {"type": "object", "title": "search_poiOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_fast", "title": null, "annotations": null, "description": "极速搜索：快速查询景点门票。数据来源：途牛旅行。", "inputSchema": {"type": "object", "title": "search_fastArguments", "required": ["query"], "properties": {"query": {"type": "string", "title": "Query", "description": "搜索词，如三亚景点、北京故宫门票、上海迪士尼"}}}, "outputSchema": {"type": "object", "title": "search_fastOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "nearby_poi", "title": null, "annotations": null, "description": "周边景点发现：基于位置搜索附近景点，返回距离、评分、地址。数据来源：高德地图。", "inputSchema": {"type": "object", "title": "nearby_poiArguments", "required": ["location"], "properties": {"city": {"type": "string", "title": "City", "default": "", "description": "所在城市，如杭州、上海、北京"}, "radius": {"type": "integer", "title": "Radius", "default": 3000, "description": "搜索半径（米），默认3000"}, "location": {"type": "string", "title": "Location", "description": "当前位置或地标，如西湖、外滩、故宫"}}}, "outputSchema": {"type": "object", "title": "nearby_poiOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_weather", "title": null, "annotations": null, "description": "查询目的地天气预报：出行前了解天气，辅助景点选择和行程安排。数据来源：高德地图。", "inputSchema": {"type": "object", "title": "search_weatherArguments", "required": ["query"], "properties": {"query": {"type": "string", "title": "Query", "description": "天气查询描述，如三亚天气预报、上海这周天气、杭州明天天气"}}}, "outputSchema": {"type": "object", "title": "search_weatherOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_transport", "title": null, "annotations": null, "description": "查询去景点的交通方案：含打车预估费用、地铁/公交换乘路线，并生成一键打车链接。数据来源：高德地图。", "inputSchema": {"type": "object", "title": "search_transportArguments", "required": ["query"], "properties": {"query": {"type": "string", "title": "Query", "description": "交通查询描述，如\'浦东机场到外滩（上海）\'\'北京南站到故宫\'\'西湖到灵隐寺（杭州）\'"}}}, "outputSchema": {"type": "object", "title": "search_transportOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}]', NULL, NULL, 1, 0, NULL, 1, '2026-11-10 18:19:02', '2026-11-10 18:26:09', NULL);
INSERT IGNORE INTO `mcp_server`
  (`id`, `server_title`, `server_name`, `transport`, `server_type`, `compile_type`, `server_config`, `envs`, `git`, `readme`, `avatar`, `description`, `server_metadata`, `tools`, `prompts`, `resources`, `is_public`, `is_recommend`, `category_id`, `user_id`, `created_time`, `updated_time`, `cover`)
VALUES
  (12, '今天吃什么', 'howtocook-mcp', 'stdio', 'local', 'package', '{"mcpServers": {"howtocook-mcp": {"cwd": null, "env": {}, "args": ["-y", "howtocook-mcp"], "icon": null, "type": null, "command": "npx", "timeout": null, "transport": "stdio", "description": null, "authentication": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/%E4%BB%8A%E5%A4%A9%E5%90%83%E4%BB%80%E4%B9%88.png', '炫一周好饭，拒绝拼好饭，基于Anduin2017/HowToCook打造的 MCP(Model Context Protocol)服务器，让 AI 助手能够为你推荐菜谱、规划膳食，解决"今天吃什么"的世纪难题！', '{"meta": null, "serverInfo": {"name": "howtocook-mcp", "title": null, "version": "0.2.2"}, "capabilities": {"tools": {"listChanged": true}, "logging": {}, "prompts": null, "resources": null, "completions": null, "experimental": null}, "instructions": null, "protocolVersion": "2025-06-18"}', '[{"meta": null, "name": "mcp_howtocook_getAllRecipes", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "获取所有菜谱", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "properties": {"no_param": {"type": "string", "description": "无参数"}}, "additionalProperties": false}, "outputSchema": null}, {"meta": null, "name": "mcp_howtocook_getRecipesByCategory", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "根据分类查询菜谱，可选分类有: 水产, 早餐, 调料, 甜品, 饮品, 荤菜, 半成品加工, 汤, 主食, 素菜", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["category"], "properties": {"category": {"enum": ["水产", "早餐", "调料", "甜品", "饮品", "荤菜", "半成品加工", "汤", "主食", "素菜"], "type": "string", "description": "菜谱分类名称，如水产、早餐、荤菜、主食等"}}, "additionalProperties": false}, "outputSchema": null}, {"meta": null, "name": "mcp_howtocook_recommendMeals", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "根据用户的忌口、过敏原、人数智能推荐菜谱，创建一周的膳食计划以及大致的购物清单", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["peopleCount"], "properties": {"allergies": {"type": "array", "items": {"type": "string"}, "description": "过敏原列表，如[\\"大蒜\\", \\"虾\\"]"}, "avoidItems": {"type": "array", "items": {"type": "string"}, "description": "忌口食材列表，如[\\"葱\\", \\"姜\\"]"}, "peopleCount": {"type": "integer", "maximum": 10, "minimum": 1, "description": "用餐人数，1-10之间的整数"}}, "additionalProperties": false}, "outputSchema": null}, {"meta": null, "name": "mcp_howtocook_whatToEat", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "不知道吃什么？根据人数直接推荐适合的菜品组合", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["peopleCount"], "properties": {"peopleCount": {"type": "integer", "maximum": 10, "minimum": 1, "description": "用餐人数，1-10之间的整数，会根据人数推荐合适数量的菜品"}}, "additionalProperties": false}, "outputSchema": null}, {"meta": null, "name": "mcp_howtocook_getRecipeById", "title": null, "execution": {"taskSupport": "forbidden"}, "annotations": null, "description": "根据菜谱名称或ID查询指定菜谱的完整详情，包括食材、步骤等", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["query"], "properties": {"query": {"type": "string", "description": "菜谱名称或ID，支持模糊匹配菜谱名称"}}, "additionalProperties": false}, "outputSchema": null}]', NULL, NULL, 1, 0, NULL, 1, '2026-11-10 18:21:54', '2026-11-10 18:23:22', NULL);
INSERT IGNORE INTO `mcp_server`
  (`id`, `server_title`, `server_name`, `transport`, `server_type`, `compile_type`, `server_config`, `envs`, `git`, `readme`, `avatar`, `description`, `server_metadata`, `tools`, `prompts`, `resources`, `is_public`, `is_recommend`, `category_id`, `user_id`, `created_time`, `updated_time`, `cover`)
VALUES
  (13, '飞猪旅行', 'FliggyTravel', 'stdio', 'local', 'package', '{"mcpServers": {"FliggyTravel": {"cwd": null, "env": {"FLYAI_API_KEY": "***"}, "args": ["mcp-fliggy-travel==6.0.0"], "icon": null, "type": null, "command": "uvx", "timeout": null, "transport": "stdio", "description": null, "authentication": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/%E9%A3%9E%E4%B9%A6%E6%97%85%E8%A1%8C.png', '一站式旅行 MCP 服务，覆盖机票、酒店、火车票、景点、美食、市内交通、万豪酒店等 11 个工具，与飞猪官方 MCP schema 100% 兼容。', '{"meta": null, "serverInfo": {"name": "fliggy-travel", "title": null, "version": ""}, "capabilities": {"tools": {"listChanged": false}, "logging": null, "prompts": {"listChanged": false}, "resources": {"subscribe": false, "listChanged": false}, "completions": null, "experimental": null}, "instructions": null, "protocolVersion": "2025-06-18"}', '[{"meta": null, "name": "travel_plan", "title": null, "annotations": null, "description": "行程规划：用自然语言描述旅行需求，智能推荐行程方案，包含交通住宿景点等。支持\\"三亚5天亲子游\\"\\"周末杭州2日游\\"等自然语言输入。\\n\\n    Args:\\n        query: 旅行需求描述，自然语言，包含目的地+天数+预算+偏好。如：三亚度蜜月5天预算1万、周末带娃去广州玩2天\\n    ", "inputSchema": {"type": "object", "title": "travel_planArguments", "required": ["query"], "properties": {"query": {"type": "string", "title": "Query"}}}, "outputSchema": {"type": "object", "title": "travel_planOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_train", "title": null, "annotations": null, "description": "火车票查询：查询火车票/高铁票/动车票的余票、价格和时刻表。支持按出发地、目的地、日期、座位等级、车型精确筛选。\\n\\n    Args:\\n        origin: 出发地，城市名（如上海、北京）。必填\\n        destination: 目的地，城市名（如北京、广州）。可选\\n        dep_date: 出发日期，格式YYYY-MM-DD。不填默认今天\\n        seat_class: 座位等级，如：商务座、一等座、二等座。可选\\n        train_type: 车型筛选，如：高铁、动车、火车。可选\\n        only_has_stock: 是否只看有票，默认false\\n    ", "inputSchema": {"type": "object", "title": "search_trainArguments", "required": ["origin"], "properties": {"origin": {"type": "string", "title": "Origin"}, "dep_date": {"type": "string", "title": "Dep Date", "default": ""}, "seat_class": {"type": "string", "title": "Seat Class", "default": ""}, "train_type": {"type": "string", "title": "Train Type", "default": ""}, "destination": {"type": "string", "title": "Destination", "default": ""}, "only_has_stock": {"type": "boolean", "title": "Only Has Stock", "default": false}}}, "outputSchema": {"type": "object", "title": "search_trainOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_flight", "title": null, "annotations": null, "description": "机票查询：查询国内航班实时票价、航班号、起降时间。支持按出发地、目的地、日期、舱位等级精确筛选。\\n\\n    Args:\\n        origin: 出发地，城市名（如上海、北京）。必填\\n        destination: 目的地，城市名（如三亚、成都）。可选\\n        dep_date: 出发日期，格式YYYY-MM-DD。不填默认今天\\n        back_date: 回程日期，格式YYYY-MM-DD。不填为单程\\n        seat_class: 舱位等级，如：经济舱、公务舱、头等舱。可选\\n        direct_only: 是否只看直飞，默认false\\n    ", "inputSchema": {"type": "object", "title": "search_flightArguments", "required": ["origin"], "properties": {"origin": {"type": "string", "title": "Origin"}, "dep_date": {"type": "string", "title": "Dep Date", "default": ""}, "back_date": {"type": "string", "title": "Back Date", "default": ""}, "seat_class": {"type": "string", "title": "Seat Class", "default": ""}, "destination": {"type": "string", "title": "Destination", "default": ""}, "direct_only": {"type": "boolean", "title": "Direct Only", "default": false}}}, "outputSchema": {"type": "object", "title": "search_flightOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_hotel", "title": null, "annotations": null, "description": "酒店搜索：搜索酒店，返回实时价格和预订链接。支持按目的地、星级、价格、关键词等多维筛选。\\n\\n    Args:\\n        dest_name: 目的地，城市或区域名（如三亚、杭州西湖）。必填\\n        check_in: 入住日期，格式YYYY-MM-DD。可选\\n        check_out: 退房日期，格式YYYY-MM-DD。可选\\n        keywords: 关键词（如亲子、商务、海景）。可选\\n        star: 酒店星级，1-5，多选用逗号分隔（如\\"4,5\\"）。可选\\n        max_price: 最高价格（元）。可选\\n        hotel_type: 酒店类型：酒店、民宿、客栈。可选\\n        bed_type: 床型：大床房、双床房、多床房。可选\\n    ", "inputSchema": {"type": "object", "title": "search_hotelArguments", "required": ["dest_name"], "properties": {"star": {"type": "string", "title": "Star", "default": ""}, "bed_type": {"type": "string", "title": "Bed Type", "default": ""}, "check_in": {"type": "string", "title": "Check In", "default": ""}, "keywords": {"type": "string", "title": "Keywords", "default": ""}, "check_out": {"type": "string", "title": "Check Out", "default": ""}, "dest_name": {"type": "string", "title": "Dest Name"}, "max_price": {"type": "integer", "title": "Max Price", "default": 0}, "hotel_type": {"type": "string", "title": "Hotel Type", "default": ""}}}, "outputSchema": {"type": "object", "title": "search_hotelOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_poi", "title": null, "annotations": null, "description": "景点门票：搜索景点门票，返回门票价格和购票链接。支持按关键词、城市、类型、等级筛选。\\n\\n    Args:\\n        keyword: 景点名称关键词（如故宫、长城）。可选\\n        city: 城市名（如杭州、西安）。可选\\n        category: 景点类型（如自然风光、主题乐园、人文古迹）。可选\\n        poi_level: 景点等级1-5（5为5A）。可选\\n        show_ticket: 是否返回门票信息，默认true\\n    ", "inputSchema": {"type": "object", "title": "search_poiArguments", "properties": {"city": {"type": "string", "title": "City", "default": ""}, "keyword": {"type": "string", "title": "Keyword", "default": ""}, "category": {"type": "string", "title": "Category", "default": ""}, "poi_level": {"type": "integer", "title": "Poi Level", "default": 0}, "show_ticket": {"type": "boolean", "title": "Show Ticket", "default": true}}}, "outputSchema": {"type": "object", "title": "search_poiOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_food", "title": null, "annotations": null, "description": "美食推荐：基于位置搜索周边餐厅美食，支持菜系筛选。返回餐厅名称、评分、人均消费和地址。数据来源：高德地图。\\n\\n    Args:\\n        query: 美食查询描述，自然语言，含地点+可选菜系。如：上海南京路附近火锅、成都春熙路美食推荐\\n    ", "inputSchema": {"type": "object", "title": "search_foodArguments", "required": ["query"], "properties": {"query": {"type": "string", "title": "Query"}}}, "outputSchema": {"type": "object", "title": "search_foodOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_transport", "title": null, "annotations": null, "description": "市内交通：查询从A到B的打车预估和公交地铁路线。返回驾车距离/时间/费用和公共交通方案。数据来源：高德地图。\\n\\n    Args:\\n        query: 交通查询描述，自然语言，含城市+出发地+目的地。如：上海浦东机场到外滩、北京天安门到王府井。用\\"到\\"连接出发地和目的地\\n    ", "inputSchema": {"type": "object", "title": "search_transportArguments", "required": ["query"], "properties": {"query": {"type": "string", "title": "Query"}}}, "outputSchema": {"type": "object", "title": "search_transportOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_fast", "title": null, "annotations": null, "description": "极速搜索：快速查询景点、酒店、度假线路等信息。适合简单关键词查询，自动识别意图。\\n\\n    Args:\\n        query: 搜索词，如：三亚酒店、北京故宫门票、三亚5天游\\n    ", "inputSchema": {"type": "object", "title": "search_fastArguments", "required": ["query"], "properties": {"query": {"type": "string", "title": "Query"}}}, "outputSchema": {"type": "object", "title": "search_fastOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_marriott_hotel", "title": null, "annotations": null, "description": "万豪酒店搜索：搜索万豪集团旗下酒店（包括万豪、喜来登、威斯汀、丽思卡尔顿等品牌）。支持按目的地、日期、价格筛选。\\n\\n    Args:\\n        dest_name: 目的地，城市或区域名（如上海、三亚）。必填\\n        check_in: 入住日期，格式YYYY-MM-DD。可选\\n        check_out: 退房日期，格式YYYY-MM-DD。可选\\n        keywords: 关键词（如商务、度假）。可选\\n        max_price: 最高价格（元）。可选\\n        bed_type: 床型：大床房、双床房。可选\\n    ", "inputSchema": {"type": "object", "title": "search_marriott_hotelArguments", "required": ["dest_name"], "properties": {"bed_type": {"type": "string", "title": "Bed Type", "default": ""}, "check_in": {"type": "string", "title": "Check In", "default": ""}, "keywords": {"type": "string", "title": "Keywords", "default": ""}, "check_out": {"type": "string", "title": "Check Out", "default": ""}, "dest_name": {"type": "string", "title": "Dest Name"}, "max_price": {"type": "integer", "title": "Max Price", "default": 0}}}, "outputSchema": {"type": "object", "title": "search_marriott_hotelOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "get_marriott_hotel_info", "title": null, "annotations": null, "description": "万豪酒店详情：获取万豪集团旗下某家酒店的详细信息。请通过万豪酒店搜索结果获取具体信息。\\n\\n    Args:\\n        hotel_name: 酒店名称（如上海外滩W酒店）。hotel_name和shid至少填一个\\n        shid: 酒店ID（如有）。hotel_name和shid至少填一个\\n        review_keyword: 评论关键词（如早餐、服务、位置）。可选\\n    ", "inputSchema": {"type": "object", "title": "get_marriott_hotel_infoArguments", "properties": {"shid": {"type": "integer", "title": "Shid", "default": 0}, "hotel_name": {"type": "string", "title": "Hotel Name", "default": ""}, "review_keyword": {"type": "string", "title": "Review Keyword", "default": ""}}}, "outputSchema": {"type": "object", "title": "get_marriott_hotel_infoOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_marriott_package", "title": null, "annotations": null, "description": "万豪套餐搜索：搜索万豪集团旗下在售的酒店套餐商品（如含早餐套餐、度假套餐等）。\\n\\n    Args:\\n        keyword: 搜索关键词。可选\\n        hotel_name: 酒店名称。可选\\n        province_or_city: 省份或城市。可选\\n    ", "inputSchema": {"type": "object", "title": "search_marriott_packageArguments", "properties": {"keyword": {"type": "string", "title": "Keyword", "default": ""}, "hotel_name": {"type": "string", "title": "Hotel Name", "default": ""}, "province_or_city": {"type": "string", "title": "Province Or City", "default": ""}}}, "outputSchema": {"type": "object", "title": "search_marriott_packageOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}]', NULL, NULL, 1, 0, NULL, 1, '2026-11-10 20:05:49', '2026-11-10 20:10:16', NULL);
INSERT IGNORE INTO `mcp_server`
  (`id`, `server_title`, `server_name`, `transport`, `server_type`, `compile_type`, `server_config`, `envs`, `git`, `readme`, `avatar`, `description`, `server_metadata`, `tools`, `prompts`, `resources`, `is_public`, `is_recommend`, `category_id`, `user_id`, `created_time`, `updated_time`, `cover`)
VALUES
  (14, 'Blender', 'blender', 'stdio', 'local', 'package', '{"mcpServers": {"blender": {"cwd": null, "env": {}, "args": ["blender-mcp"], "icon": null, "type": null, "command": "uvx", "timeout": null, "transport": "stdio", "description": null, "authentication": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/blender.png', 'BlenderMCP 通过模型上下文协议 (MCP) 将 Blender 连接到 Claude AI，使 Claude 能够直接与 Blender 交互并控制它。此集成支持通过提示辅助进行3D建模、场景创建和操作。', '{"meta": null, "serverInfo": {"name": "MCP for Blender", "title": null, "version": "1.30.0"}, "capabilities": {"tools": {"listChanged": false}, "logging": null, "prompts": {"listChanged": false}, "resources": {"subscribe": false, "listChanged": false}, "completions": null, "experimental": {}}, "instructions": "MCP for Blender drives the user\'s live Blender. execute_blender_code runs Python there\\nwith the full bpy API, so anything Blender can do, you can do; look shows you the result.\\n\\nStart with get_addon_status (Blender version, which libraries and generators are on) and\\nget_scene_info.\\n\\nScripts run in someone else\'s Blender:\\n- Look shader nodes up by type, never by name (names are localized):\\n  `next(n for n in mat.node_tree.nodes if n.type == \\"BSDF_PRINCIPLED\\")`.\\n- Never hardcode enum identifiers; read them, e.g.\\n  `[i.identifier for i in bpy.types.RenderSettings.bl_rna.properties[\\"file_format\\"].enum_items]`.\\n  scene.render.engine under-reports: read the current value, and assign a new one inside\\n  try/except TypeError, whose message lists the valid engines.\\n- Material colors go on shader node inputs; material.diffuse_color only affects the viewport.\\n\\nlook is how you see your work; use it as much as you need. Images stay in the conversation, so\\na smaller max_size keeps long sessions cheap.\\n\\nObjects can also come from existing libraries (search_assets, then import_asset: Poly Haven,\\nSketchfab, Poly Pizza) or be made to order (generate_3d: one new textured model from text or an\\nimage, 1-3 minutes, may cost the user a credit). A generation is one object, never a whole\\nscene, the ground or parts to assemble. Imported and generated models arrive at arbitrary\\nscale: use the reported world_bounding_box to size them and put them on the ground.", "protocolVersion": "2025-06-18"}', '[{"meta": null, "name": "get_addon_status", "title": null, "annotations": null, "description": "\\n    Check the connected Blender: its version, whether the addon matches this server, and which\\n    asset libraries and 3D generators are switched on. Call it once at the start.\\n\\n    `libraries` are the search_assets sources and `generators` the generate_3d providers, each\\n    on or off for this user. \\"(Premium)\\" ones come with MCP for Blender Premium and don\'t use the\\n    user\'s own API keys. When pointing the user to Premium, link\\n    https://mcp-for-blender.com/premium?ref=mcp-status\\n\\n    If outdated, tells the user how to update via `uvx mcp-for-blender install-addon`\\n    (then restart or re-enable the addon in Blender).\\n\\n    `telemetry_consent` reports whether data collection is on, off, or null if\\n    Blender could not be reached. Use it to answer telemetry status questions.\\n    ", "inputSchema": {"type": "object", "title": "get_addon_statusArguments", "properties": {"user_prompt": {"type": "string", "title": "User Prompt", "default": ""}}}, "outputSchema": {"type": "object", "title": "get_addon_statusOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "disable_telemetry", "title": null, "annotations": null, "description": "\\n    Turn OFF collection of prompts, code, screenshots and scene data.\\n\\n    Use this whenever the user asks to stop data collection, opt out of\\n    telemetry, or stop sharing their data. Takes effect immediately.\\n\\n    This tool can only turn collection OFF. Turning it back on is done by the\\n    user in Blender under Preferences > Add-ons > Blender MCP.\\n    ", "inputSchema": {"type": "object", "title": "disable_telemetryArguments", "properties": {"user_prompt": {"type": "string", "title": "User Prompt", "default": ""}}}, "outputSchema": {"type": "object", "title": "disable_telemetryOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "get_scene_info", "title": null, "annotations": null, "description": "\\n    Facts about the scene as text: what\'s there, where, how big, and how healthy meshes and rigs\\n    are. No image; to see the scene, use look.\\n\\n    One header line (object counts, active, selection, mode), then one line per object with the\\n    fields you ask for. Top-level objects by default; root=\\"Name\\" lists that object\'s hierarchy,\\n    query=\\"chair\\" lists every object whose name contains the text. For anything else about an\\n    object, read it with execute_blender_code.\\n\\n    Parameters:\\n    - fields: What to show per object (default: location, size, children, hidden).\\n      placement: location (world), size (world bounding box), ground (on ground, floating or\\n        below by), rotation (degrees), scale, parent\\n      contents: children (count), hidden, details (faces, bones or light power), materials,\\n        modifiers, animation\\n      health: topology (quads, tris, ngons, non-manifold and boundary edges, loose verts,\\n        poles), weights (vertices no deform bone moves, deform bones with no vertex group)\\n      settings: adds a line with the file, engine, frame range, resolution, camera, HDRI and\\n        unit scale\\n    - query: Name filter across all objects.\\n    - root: Object whose hierarchy to list.\\n    - limit: Maximum object lines (default 20).\\n    - user_prompt: The user\'s own words describing what they want, quoted verbatim.\\n    ", "inputSchema": {"type": "object", "title": "get_scene_infoArguments", "properties": {"root": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Root", "default": null}, "limit": {"type": "integer", "title": "Limit", "default": 20}, "query": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Query", "default": null}, "fields": {"anyOf": [{"type": "array", "items": {"type": "string"}}, {"type": "null"}], "title": "Fields", "default": null}, "user_prompt": {"type": "string", "title": "User Prompt", "default": ""}}}, "outputSchema": {"type": "object", "title": "get_scene_infoOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "execute_blender_code", "title": null, "annotations": null, "description": "\\n    Run Python in the user\'s live Blender (bpy, bmesh, mathutils). Whatever it prints is returned.\\n\\n    Work in small steps and print what you need to know.\\n\\n    Parameters:\\n    - code: The Python code to execute\\n    - user_prompt: The user\'s own words describing what they want, quoted verbatim (do not paraphrase or summarise). Pass the same goal on every call in a multi-step task so each action is linked to the intent behind it. Never substitute your own sub-goal, plan step, or status text; if the user has given no new instruction, repeat their previous words unchanged.\\n    ", "inputSchema": {"type": "object", "title": "execute_blender_codeArguments", "required": ["code"], "properties": {"code": {"type": "string", "title": "Code"}, "user_prompt": {"type": "string", "title": "User Prompt", "default": ""}}}, "outputSchema": {"type": "object", "title": "execute_blender_codeOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "record_trajectory_feedback", "title": null, "annotations": null, "description": "\\n    Record evaluation feedback for a captured trajectory step.\\n\\n    Call it when the user reacts to a result: \\"accept\\" when they keep it (\\"looks good\\"),\\n    \\"reject\\" or \\"undo\\" when they reject it or ask to undo, and \\"correction\\" with their words\\n    as correction_text when they correct you (\\"too dark\\", \\"make it taller\\").\\n\\n    Parameters:\\n    - feedback: One of accept | reject | undo | correction\\n    - correction_text: Optional free-text correction or follow-up (especially for correction)\\n    - step_index: Optional 0-based step index; defaults to the last recorded step\\n    - user_prompt: Optional goal/prompt context for the feedback row\\n    ", "inputSchema": {"type": "object", "title": "record_trajectory_feedbackArguments", "required": ["feedback"], "properties": {"feedback": {"type": "string", "title": "Feedback"}, "step_index": {"anyOf": [{"type": "integer"}, {"type": "null"}], "title": "Step Index", "default": null}, "user_prompt": {"type": "string", "title": "User Prompt", "default": ""}, "correction_text": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Correction Text", "default": null}}}, "outputSchema": {"type": "object", "title": "record_trajectory_feedbackOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": {"ui": {"resourceUri": "ui://mcp-for-blender/viewport-v2"}}, "name": "look", "title": null, "annotations": null, "description": "\\n    See the scene as one image. For counts, sizes and positions, use get_scene_info.\\n\\n    Choose where from (mode) and how it\'s drawn (shading):\\n    - mode: viewport (what the user sees; default), camera (through the scene camera, at the\\n      render aspect), angles (the target from several sides, auto-framed; default front, right,\\n      top, three_quarter), frames (a strip over the animation).\\n    - shading: solid, material, rendered (EEVEE and Workbench only), wireframe (edges over a\\n      plain surface), xray (see-through, bones in front). Default: the viewport\'s.\\n    - image: Instead of the scene, show this image: \\"Render Result\\" after a render, another\\n      image in the file, or a file path.\\n\\n    Parameters:\\n    - target: Object names to frame (children included). Default: every visible object.\\n    - views: For angles: up to 6 of front, back, left, right, top, three_quarter, or [x, y, z]\\n      directions from the target towards the eye ([0, -1, 0.2] is front, slightly above).\\n    - distance: Metres from the target\'s centre to the eye, for angles and frames views. Default:\\n      far enough to fit it; closer for detail or to stand inside a room.\\n    - frames / frame_count: For frames: explicit frame numbers, or how many to sample (2-12).\\n    - view: For frames: \\"camera\\", an angle name or an [x, y, z] direction; default the viewport.\\n    - max_size: Longest side in pixels (default 768). Images stay in the conversation, so go\\n      smaller for quick checks and larger only to read fine detail.\\n    - user_prompt: The user\'s own words describing what they want, quoted verbatim.\\n\\n    Every setting changed to take the picture is restored afterwards.\\n    ", "inputSchema": {"type": "object", "title": "lookArguments", "properties": {"mode": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Mode", "default": null}, "view": {"anyOf": [{"type": "string"}, {"type": "array", "items": {"type": "number"}}, {"type": "null"}], "title": "View", "default": null}, "image": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Image", "default": null}, "views": {"anyOf": [{"type": "array", "items": {"anyOf": [{"type": "string"}, {"type": "array", "items": {"type": "number"}}]}}, {"type": "null"}], "title": "Views", "default": null}, "frames": {"anyOf": [{"type": "array", "items": {"type": "integer"}}, {"type": "null"}], "title": "Frames", "default": null}, "target": {"anyOf": [{"type": "array", "items": {"type": "string"}}, {"type": "null"}], "title": "Target", "default": null}, "shading": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Shading", "default": null}, "distance": {"anyOf": [{"type": "number"}, {"type": "null"}], "title": "Distance", "default": null}, "max_size": {"type": "integer", "title": "Max Size", "default": 768}, "frame_count": {"type": "integer", "title": "Frame Count", "default": 6}, "user_prompt": {"type": "string", "title": "User Prompt", "default": ""}}}, "outputSchema": null}, {"meta": null, "name": "generate_3d", "title": null, "annotations": null, "description": "\\n    Make one new textured 3D model from a text prompt or an image, and import it.\\n\\n    One object per call: not a whole scene, the ground, or parts to assemble. It arrives at\\n    arbitrary scale and facing (meshy: real-world size, origin at the bottom). Each call can cost\\n    the user money or a monthly generation, so duplicate a generated object for repeats.\\n\\n    Waits up to wait_seconds (at most 45), then imports. Generation usually takes 1-3 minutes: if\\n    it isn\'t done in time you get a job handle; call generate_3d(job=..., name=...) again to keep\\n    waiting. Repeating a request whose generation is still unfinished resumes it instead of paying\\n    again.\\n\\n    Parameters:\\n    - prompt: Short English description of one object (\\"weathered wooden treasure chest\\").\\n    - image: Instead of a prompt: an absolute image file path or an http(s) URL. Images attached in\\n      chat can\'t be passed: ask the user for a path or URL, don\'t fall back to text without asking.\\n      hyper3d also takes a folder of up to 5 images, as views of one object (Premium uses the first).\\n    - name: Object name in the scene. Defaults to one made from the prompt.\\n    - provider: auto (default), tripo, hunyuan3d, hyper3d or meshy. Auto prefers the user\'s MCP for\\n      Blender Premium generators, then their own API keys.\\n    - quality: \\"standard\\" or \\"high\\" (Premium; not Meshy, and not Tripo on your own key). Omit for\\n      the user\'s default; \\"high\\" only when the user asks for more detail.\\n    - bbox_condition: hyper3d only: [length, width, height] proportions.\\n    - pose_mode: meshy only: \\"a-pose\\" or \\"t-pose\\" when the user asks for a character in an A-pose\\n      or T-pose (often to rig it).\\n    - job: A handle from an earlier call, to resume waiting for it.\\n    - user_prompt: The user\'s own words describing what they want, quoted verbatim.\\n    ", "inputSchema": {"type": "object", "title": "generate_3dArguments", "properties": {"job": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Job", "default": null}, "name": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Name", "default": null}, "image": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Image", "default": null}, "prompt": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Prompt", "default": null}, "quality": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Quality", "default": null}, "provider": {"type": "string", "title": "Provider", "default": "auto"}, "pose_mode": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Pose Mode", "default": null}, "user_prompt": {"type": "string", "title": "User Prompt", "default": ""}, "wait_seconds": {"type": "integer", "title": "Wait Seconds", "default": 50}, "bbox_condition": {"anyOf": [{"type": "array", "items": {"type": "number"}}, {"type": "null"}], "title": "Bbox Condition", "default": null}}}, "outputSchema": {"type": "object", "title": "generate_3dOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}, {"meta": null, "name": "search_assets", "title": null, "annotations": null, "description": "\\n    Search a library of existing assets. The sources:\\n    - polyhaven: HDRIs, PBR textures and realistic models, all CC0. Search understands intent and\\n      synonyms (\\"couch\\" finds sofas).\\n    - sketchfab: a large catalogue of user-made models, realistic and specific ones included;\\n      licences and face counts vary per model.\\n    - polypizza: stylised low-poly models, CC0 or CC-BY (credit the creator).\\n\\n    Parameters:\\n    - source: polyhaven, sketchfab or polypizza.\\n    - query: What you\'re looking for, in plain words.\\n    - asset_type: polyhaven only: hdris, textures, models or all.\\n    - category: Optional. polyhaven: a category path (\\"Metal/Sheet & Corrugated\\"). sketchfab:\\n      comma-separated categories. polypizza: e.g. \\"Furniture & Decor\\", \\"Nature\\", \\"Animals\\".\\n    - attributes: polyhaven only: filters like {\\"weather\\": \\"clear\\"}; an unknown key errors with the\\n      valid ones.\\n    - min_size_m: polyhaven only: minimum real-world size in metres. Use 2+ for walls, floors and\\n      ground so textures don\'t visibly repeat.\\n    - licence: polypizza only: \\"CC0\\" or \\"CC-BY\\".\\n    - animated: polypizza only: animated models only.\\n    - limit: Number of results.\\n    - previews: Attach thumbnails of the first N results (max 6; polyhaven and sketchfab). Cheaper\\n      than importing the wrong asset.\\n    - user_prompt: The user\'s own words describing what they want, quoted verbatim.\\n\\n    Results include each asset\'s id; pass it to import_asset.\\n    ", "inputSchema": {"type": "object", "title": "search_assetsArguments", "required": ["source"], "properties": {"limit": {"type": "integer", "title": "Limit", "default": 20}, "query": {"type": "string", "title": "Query", "default": ""}, "source": {"type": "string", "title": "Source"}, "licence": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Licence", "default": null}, "animated": {"type": "boolean", "title": "Animated", "default": false}, "category": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Category", "default": null}, "previews": {"type": "integer", "title": "Previews", "default": 0}, "asset_type": {"type": "string", "title": "Asset Type", "default": "all"}, "attributes": {"anyOf": [{"type": "object", "additionalProperties": true}, {"type": "null"}], "title": "Attributes", "default": null}, "min_size_m": {"anyOf": [{"type": "number"}, {"type": "null"}], "title": "Min Size M", "default": null}, "user_prompt": {"type": "string", "title": "User Prompt", "default": ""}}}, "outputSchema": null}, {"meta": null, "name": "import_asset", "title": null, "annotations": null, "description": "\\n    Download an asset found with search_assets and bring it into the scene.\\n\\n    Parameters:\\n    - source: polyhaven, sketchfab or polypizza.\\n    - id: The asset\'s id (UID for sketchfab) from search_assets.\\n    - asset_type: polyhaven only, required: hdris (becomes the world lighting), textures (builds a\\n      PBR material) or models.\\n    - target_size: Size in metres of the model\'s largest dimension (chair 1.0, car 4.5, cup 0.12).\\n      Required for sketchfab, recommended for polypizza; library models come at arbitrary scale.\\n    - apply_to: polyhaven textures: object names to put the material on (replaces their materials).\\n      Without it the material is created but unused, and is lost if the file is saved.\\n    - resolution: polyhaven: 1k, 2k, 4k or 8k. 1k-2k for background, 4k for close-ups.\\n    - file_format: polyhaven, optional: hdr/exr for HDRIs, jpg/png/exr for textures.\\n    - user_prompt: The user\'s own words describing what they want, quoted verbatim.\\n\\n    Afterwards check the reported bounding box, put the object on the ground, and look at it.\\n    ", "inputSchema": {"type": "object", "title": "import_assetArguments", "required": ["source", "id"], "properties": {"id": {"type": "string", "title": "Id"}, "source": {"type": "string", "title": "Source"}, "apply_to": {"anyOf": [{"type": "array", "items": {"type": "string"}}, {"type": "null"}], "title": "Apply To", "default": null}, "asset_type": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Asset Type", "default": null}, "resolution": {"type": "string", "title": "Resolution", "default": "1k"}, "file_format": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "File Format", "default": null}, "target_size": {"anyOf": [{"type": "number"}, {"type": "null"}], "title": "Target Size", "default": null}, "user_prompt": {"type": "string", "title": "User Prompt", "default": ""}}}, "outputSchema": {"type": "object", "title": "import_assetOutput", "required": ["result"], "properties": {"result": {"type": "string", "title": "Result"}}}}]', NULL, '[{"uri": "ui://mcp-for-blender/viewport-v2", "meta": {"ui": {"prefersBorder": false}, "openai/ui": {"preferredDisplayMode": "fullscreen", "availableDisplayModes": ["fullscreen"]}}, "name": "viewport", "size": null, "title": "Blender Viewport", "mimeType": "text/html;profile=mcp-app", "annotations": null, "description": ""}]', 1, 0, NULL, 1, '2026-11-10 20:05:53', '2026-11-10 20:12:11', NULL);
INSERT IGNORE INTO `mcp_server`
  (`id`, `server_title`, `server_name`, `transport`, `server_type`, `compile_type`, `server_config`, `envs`, `git`, `readme`, `avatar`, `description`, `server_metadata`, `tools`, `prompts`, `resources`, `is_public`, `is_recommend`, `category_id`, `user_id`, `created_time`, `updated_time`, `cover`)
VALUES
  (15, '可视化图表', 'mcp-server-chart', 'stdio', 'local', 'package', '{"mcpServers": {"mcp-server-chart": {"cwd": null, "env": {}, "args": ["-y", "@antv/mcp-server-chart"], "icon": null, "type": null, "command": "npx", "timeout": null, "transport": "stdio", "description": null, "authentication": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/%E5%8F%AF%E8%A7%86%E5%8C%96%E5%9B%BE%E8%A1%A8.png', '一个用于生成图表的 Model Context Protocol 服务器，使用 AntV。\n\n这是一个基于 TypeScript 的 MCP 服务器，提供图表生成功能。它允许您通过 MCP 工具创建各种类型的图表。', '{"meta": null, "serverInfo": {"name": "mcp-server-chart", "title": null, "version": "0.8.x"}, "capabilities": {"tools": {"listChanged": null}, "logging": null, "prompts": null, "resources": null, "completions": null, "experimental": null}, "instructions": null, "protocolVersion": "2025-06-18"}', '[{"meta": null, "name": "generate_area_chart", "title": null, "annotations": {"title": "Generate Area Chart", "readOnlyHint": true, "openWorldHint": null, "idempotentHint": null, "destructiveHint": null}, "description": "Generate a area chart to show data trends under continuous independent variables and observe the overall data trend, such as, displacement = velocity (average or instantaneous) × time: s = v × t. If the x-axis is time (t) and the y-axis is velocity (v) at each moment, an area chart allows you to observe the trend of velocity over time and infer the distance traveled by the area\'s size.", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["data"], "properties": {"data": {"type": "array", "items": {"type": "object", "required": ["time", "value"], "properties": {"time": {"type": "string"}, "group": {"type": "string"}, "value": {"type": "number"}}}, "minItems": 1, "description": "Data for area chart, it should be an array of objects, each object contains a `time` field and a `value` field, such as, [{ time: \'2015\', value: 23 }, { time: \'2016\', value: 32 }], when stacking is needed for area, the data should contain a `group` field, such as, [{ time: \'2015\', value: 23, group: \'A\' }, { time: \'2015\', value: 32, group: \'B\' }]."}, "stack": {"type": "boolean", "default": false, "description": "Whether stacking is enabled. When enabled, area charts require a \'group\' field in the data."}, "style": {"type": "object", "properties": {"palette": {"type": "array", "items": {"type": "string"}, "description": "Color palette for the chart, it is a collection of colors."}, "texture": {"enum": ["default", "rough"], "type": "string", "default": "default", "description": "Set the texture for the chart, optional, default is \'default\'. \'rough\' refers to hand-drawn style."}, "lineWidth": {"type": "number", "description": "Line width for the lines of chart, such as 4."}, "backgroundColor": {"type": "string", "description": "Background color of the chart, such as, \'#fff\'."}}, "description": "Style configuration for the chart with a JSON object, optional."}, "theme": {"enum": ["default", "academy", "dark"], "type": "string", "default": "default", "description": "Set the theme for the chart, optional, default is \'default\'."}, "title": {"type": "string", "default": "", "description": "Set the title of chart."}, "width": {"type": "number", "default": 600, "description": "Set the width of chart, default is 600."}, "height": {"type": "number", "default": 400, "description": "Set the height of chart, default is 400."}, "axisXTitle": {"type": "string", "default": "", "description": "Set the x-axis title of chart."}, "axisYTitle": {"type": "string", "default": "", "description": "Set the y-axis title of chart."}}}, "outputSchema": null}, {"meta": null, "name": "generate_bar_chart", "title": null, "annotations": {"title": "Generate Bar Chart", "readOnlyHint": true, "openWorldHint": null, "idempotentHint": null, "destructiveHint": null}, "description": "Generate a horizontal bar chart to show data for numerical comparisons among different categories, such as, comparing categorical data and for horizontal comparisons.", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["data"], "properties": {"data": {"type": "array", "items": {"type": "object", "required": ["category", "value"], "properties": {"group": {"type": "string"}, "value": {"type": "number"}, "category": {"type": "string"}}}, "minItems": 1, "description": "Data for bar chart, such as, [{ category: \'分类一\', value: 10 }, { category: \'分类二\', value: 20 }], when grouping or stacking is needed for bar, the data should contain a `group` field, such as, when [{ category: \'北京\', value: 825, group: \'油车\' }, { category: \'北京\', value: 1000, group: \'电车\' }]."}, "group": {"type": "boolean", "default": false, "description": "Whether grouping is enabled. When enabled, bar charts require a \'group\' field in the data. When `group` is true, `stack` should be false."}, "stack": {"type": "boolean", "default": true, "description": "Whether stacking is enabled. When enabled, bar charts require a \'group\' field in the data. When `stack` is true, `group` should be false."}, "style": {"type": "object", "properties": {"palette": {"type": "array", "items": {"type": "string"}, "description": "Color palette for the chart, it is a collection of colors."}, "texture": {"enum": ["default", "rough"], "type": "string", "default": "default", "description": "Set the texture for the chart, optional, default is \'default\'. \'rough\' refers to hand-drawn style."}, "backgroundColor": {"type": "string", "description": "Background color of the chart, such as, \'#fff\'."}}, "description": "Style configuration for the chart with a JSON object, optional."}, "theme": {"enum": ["default", "academy", "dark"], "type": "string", "default": "default", "description": "Set the theme for the chart, optional, default is \'default\'."}, "title": {"type": "string", "default": "", "description": "Set the title of chart."}, "width": {"type": 