 "Label for the venn chart segment, such as \'A\', \'B\', or \'C\'."}, "value": {"type": "number", "description": "Value for the venn chart segment, such as 10, 20, or 30."}}}, "minItems": 1, "description": "Data for venn chart, such as, [{ label: \'A\', value: 10, sets: [\'A\'] }, { label: \'B\', value: 20, sets: [\'B\'] }, { label: \'C\', value: 30, sets: [\'C\'] }, { label: \'AB\', value: 5, sets: [\'A\', \'B\'] }]."}, "style": {"type": "object", "properties": {"palette": {"type": "array", "items": {"type": "string"}, "description": "Color palette for the chart, it is a collection of colors."}, "texture": {"enum": ["default", "rough"], "type": "string", "default": "default", "description": "Set the texture for the chart, optional, default is \'default\'. \'rough\' refers to hand-drawn style."}, "backgroundColor": {"type": "string", "description": "Background color of the chart, such as, \'#fff\'."}}, "description": "Style configuration for the chart with a JSON object, optional."}, "theme": {"enum": ["default", "academy", "dark"], "type": "string", "default": "default", "description": "Set the theme for the chart, optional, default is \'default\'."}, "title": {"type": "string", "default": "", "description": "Set the title of chart."}, "width": {"type": "number", "default": 600, "description": "Set the width of chart, default is 600."}, "height": {"type": "number", "default": 400, "description": "Set the height of chart, default is 400."}}}, "outputSchema": null}, {"meta": null, "name": "generate_violin_chart", "title": null, "annotations": {"title": "Generate Violin Chart", "readOnlyHint": true, "openWorldHint": null, "idempotentHint": null, "destructiveHint": null}, "description": "Generate a violin chart to show data for statistical summaries among different categories, such as, comparing the distribution of data points across categories.", "inputSchema": {"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["data"], "properties"