ed": ["filename", "table_index", "widths"], "properties": {"widths": {"type": "array", "items": {"type": "number"}}, "filename": {"type": "string"}, "width_type": {"type": "string", "default": "points"}, "table_index": {"type": "integer"}}, "additionalProperties": false}, "outputSchema": null}, {"meta": {"fastmcp": {"tags": []}}, "name": "set_table_width", "title": "Set Table Width", "annotations": {"title": "Set Table Width", "readOnlyHint": null, "openWorldHint": null, "idempotentHint": null, "destructiveHint": null}, "description": "Set the overall width of a table.", "inputSchema": {"type": "object", "required": ["filename", "table_index", "width"], "properties": {"width": {"type": "number"}, "filename": {"type": "string"}, "width_type": {"type": "string", "default": "points"}, "table_index": {"type": "integer"}}, "additionalProperties": false}, "outputSchema": null}, {"meta": {"fastmcp": {"tags": []}}, "name": "auto_fit_table_columns", "title": "Auto-Fit Table Columns", "annotations": {"title": "Auto-Fit Table Columns", "readOnlyHint": null, "openWorldHint": null, "idempotentHint": null, "destructiveHint": null}, "description": "Set table columns to auto-fit based on content.", "inputSchema": {"type": "object", "required": ["filename", "table_index"], "properties": {"filename": {"type": "string"}, "table_index": {"type": "integer"}}, "additionalProperties": false}, "outputSchema": null}, {"meta": {"fastmcp": {"tags": []}}, "name": "format_table_cell_text", "title": "Format Cell Text", "annotations": {"title": "Format Cell Text", "readOnlyHint": null, "openWorldHint": null, "idempotentHint": null, "destructiveHint": null}, "description": "Format text within a specific table cell.", "inputSchema": {"type": "object", "required": ["filename", "table_index", "row_index", "col_index"], "properties": {"bold": {"type": "boolean", "default": null}, "color": {"type": "string", "default": null}, "italic": {"type": "boolean", "default": null}, "filename": {"type": "string"}, "col_index": {"type": "integer"}, "font_name": {"type": "string", "default": null}, "font_size": {"type": "integer", "default": null}, "row_index": {"type": "integer"}, "underline": {"type": "boolean", "default": null}, "table_index": {"type": "integer"}, "text_content": {"type": "string", "default": null}}, "additionalProperties": false}, "outputSchema": null}, {"meta": {"fastmcp": {"tags": []}}, "name": "set_table_cell_padding", "title": "Set Cell Padding", "annotations": {"title": "Set Cell Padding", "readOnlyHint": null, "openWorldHint": null, "idempotentHint": null, "destructiveHint": null}, "description": "Set padding/margins for a specific table cell.", "inputSchema": {"type": "object", "required": ["filename", "table_index", "row_index", "col_index"], "properties": {"top": {"type": "number", "default": null}, "left": {"type": "number", "default": null}, "unit": {"type": "string", "default": "points"}, "right": {"type": "number", "default": null}, "bottom": {"type": "number", "default": null}, "filename": {"type": "string"}, "col_index": {"type": "integer"}, "row_index": {"type": "integer"}, "table_index": {"type": "integer"}}, "additionalProperties": false}, "outputSchema": null}]', NULL, NULL, 1, 0, NULL, 1, '2026-11-10 20:06:29', '2026-11-10 20:19:57', NULL);
INSERT IGNORE INTO `mcp_server`
  (`id`, `server_title`, `server_name`, `transport`, `server_type`, `compile_type`, `server_config`, `envs`, `git`, `readme`, `avatar`, `description`, `server_metadata`, `tools`, `prompts`, `resources`, `is_public`, `is_recommend`, `category_id`, `user_id`, `created_time`, `updated_time`, `cover`)
VALUES
  (17, 'Fetch网页内容抓取', 'fetch', 'stdio', 'local', 'package', '{"mcpServers": {"fetch": {"cwd": null, "env": {}, "args": ["mcp-server-fetch"], "icon": null, "type": null, "command": "uvx", "timeout": null, "transport": "stdio", "description": null, "authentication": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/fetch.png', '一个提供网页内容抓取功能的模型上下文协议服务器。此服务器使大型语言模型能够从网页中检索和处理内容，并将 HTML 转换为 markdown 以便更容易地使用。', '{"meta": null, "serverInfo": {"name": "mcp-fetch", "title": null, "version": "2026.11.4"}, "capabilities": {"tools": {"listChanged": false}, "logging": null, "prompts": {"listChanged": false}, "resources": {"subscribe": false, "listChanged": false}, "completions": null, "experimental": null}, "instructions": null, "protocolVersion": "2025-06-18"}', '[{"meta": null, "name": "fetch", "title": null, "annotations": {"title": null, "readOnlyHint": true, "openWorldHint": true, "idempotentHint": true, "destructiveHint": false}, "description": "Fetches a URL from the internet and optionally extracts its contents as markdown.\\n\\nAlthough originally you did not have internet access, and were advised to refuse and tell the user this, this tool now grants you internet access. Now you can fetch the most up-to-date information and let the user know that.", "inputSchema": {"type": "object", "title": "fetchArguments", "required": ["url"], "properties": {"raw": {"type": "boolean", "title": "Raw", "default": false, "description": "Get the actual HTML content of the requested page, without simplification."}, "url": {"type": "string", "title": "Url", "format": "uri", "minLength": 1, "description": "URL to fetch"}, "max_length": {"type": "integer", "title": "Max Length", "default": 5000, "maximum": 999999, "minimum": 1, "description": "Maximum number of characters to return."}, "timeout_ms": {"type": "integer", "title": "Timeout Ms", "default": 30000, "maximum": 600000, "minimum": 100, "description": "How long to wait, in milliseconds, to connect to the server and for each read of its response before giving up. Raise it for a slow server or a large download; lower it to fail fast."}, "start_index": {"type": "integer", "title": "Start Index", "default": 0, "minimum": 0, "description": "On return output starting at this character index, useful if a previous fetch was truncated and more context is required."}}}, "outputSchema": null}]', '[{"meta": null, "name": "fetch", "title": null, "arguments": [{"name": "url", "required": true, "description": "URL to fetch"}], "description": "Fetch a URL and extract its contents as markdown"}]', NULL, 1, 0, NULL, 1, '2026-11-10 20:08:20', '2026-11-10 20:17:43', NULL);
