  (18, '民宿搜索', 'airbnb', 'stdio', 'local', 'package', '{"mcpServers": {"airbnb": {"cwd": null, "env": {}, "args": ["-y", "@openbnb/mcp-server-airbnb"], "icon": null, "type": null, "command": "npx", "timeout": null, "transport": "stdio", "description": null, "authentication": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/%E6%B0%91%E5%AE%BF%E6%90%9C%E7%B4%A2.png', '用于搜索 Airbnb 并获取房源详细信息的 MCP 服务器。\n\n', '{"meta": null, "serverInfo": {"name": "airbnb", "title": null, "version": "0.3.0"}, "capabilities": {"tools": {"listChanged": null}, "logging": null, "prompts": null, "resources": null, "completions": null, "experimental": null}, "instructions": null, "protocolVersion": "2025-06-18"}', '[{"meta": null, "name": "airbnb_search", "title": null, "annotations": null, "description": "Search for Airbnb listings with various filters and pagination. Provide direct links to the user", "inputSchema": {"type": "object", "required": ["location"], "properties": {"pets": {"type": "number", "description": "Number of pets"}, "adults": {"type": "number", "description": "Number of adults"}, "cursor": {"type": "string", "description": "Base64-encoded string used for Pagination"}, "checkin": {"type": "string", "description": "Check-in date (YYYY-MM-DD)"}, "infants": {"type": "number", "description": "Number of infants"}, "placeId": {"type": "string", "description": "Google Maps Place ID (overrides the location parameter)"}, "checkout": {"type": "string", "description": "Check-out date (YYYY-MM-DD)"}, "children": {"type": "number", "description": "Number of children"}, "location": {"type": "string", "description": "Location to search for (city, state, etc.)"}, "maxPrice": {"type": "number", "description": "Maximum price for the stay"}, "minPrice": {"type": "number", "description": "Minimum price for the stay"}, "propertyType": {"enum": ["entire_home", "private_room", "shared_room", "hotel_room"], "type": "string", "description": "Filter by property type: \'entire_home\' (entire homes/apartments), \'private_room\' (private rooms in shared homes), \'shared_room\' (shared/dorm-style rooms), \'hotel_room\' (hotel rooms)"}, "ignoreRobotsText": {"type": "boolean", "description": "Ignore robots.txt rules for this request"}}}, "outputSchema": null}, {"meta": null, "name": "airbnb_listing_details", "title": null, "annotations": null, "description": "Get detailed information about a specific Airbnb listing. Provide direct links to the user", "inputSchema": {"type": "object", "required": ["id"], "properties": {"id": {"type": "string", "description": "The Airbnb listing ID"}, "pets": {"type": "number", "description": "Number of pets"}, "adults": {"type": "number", "description": "Number of adults"}, "checkin": {"type": "string", "description": "Check-in date (YYYY-MM-DD)"}, "infants": {"type": "number", "description": "Number of infants"}, "checkout": {"type": "string", "description": "Check-out date (YYYY-MM-DD)"}, "children": {"type": "number", "description": "Number of children"}, "ignoreRobotsText": {"type": "boolean", "description": "Ignore robots.txt rules for this request"}}}, "outputSchema": null}]', NULL, NULL, 1, 0, NULL, 1, '2026-11-10 20:28:01', '2026-11-10 20:29:36', NULL);
