  (19, 'Git 提交助手', 'git-commit-aider', 'stdio', 'local', 'package', '{"mcpServers": {"git-commit-aider": {"cwd": null, "env": {}, "args": ["mcp-git-commit-aider"], "icon": null, "type": null, "command": "npx", "timeout": null, "transport": "stdio", "description": null, "authentication": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/git%E5%8A%A9%E6%89%8B.png', '代表 AI 进行 git 提交，以便您可以在代码库中跟踪 AI 的贡献。\n这是一个基于 TypeScript 的 MCP 服务器，提供了一个工具，用于提交 Git 仓库中的暂存更改，并在提交者的名称后追加 "(aider)"。', '{"meta": null, "serverInfo": {"name": "git-commit-aider", "title": null, "version": "0.1.0", "description": "Make git commits on behalf of AI, so that you can track AI contribution in your codebase"}, "capabilities": {"tools": {"listChanged": null}, "logging": null, "prompts": null, "resources": null, "completions": null, "experimental": null}, "instructions": null, "protocolVersion": "2024-11-05"}', '[{"meta": null, "name": "commit_staged", "title": null, "annotations": null, "description": "Commit staged changes with a specific message, appending \\"(aider)\\" to the committer name.", "inputSchema": {"type": "object", "required": ["message"], "properties": {"cwd": {"type": "string", "description": "Optional: The working directory for the git command (defaults to the workspace root)."}, "message": {"type": "string", "description": "The commit message."}}}, "outputSchema": null}]', NULL, NULL, 1, 0, NULL, 1, '2026-11-10 20:31:16', '2026-11-10 20:33:11', NULL);
