  (20, 'MySQL智能服务', 'mysql', 'stdio', 'local', 'package', '{"mcpServers": {"mysql": {"cwd": null, "env": {"MYSQL_HOST": "127.0.0.1", "MYSQL_PORT": "3306", "MYSQL_USER": "root", "MYSQL_DATABASE": "asclaw", "MYSQL_PASSWORD": "***"}, "args": ["mysql_mcp_server"], "icon": null, "type": null, "command": "uvx", "timeout": null, "transport": "stdio", "description": null, "authentication": null}}}', NULL, NULL, NULL, 'https://asclaw-1252895433.cos.ap-beijing.myqcloud.com/asclaw/mcp_images/mysql.png', '一个提供 MySQL 数据库操作的 Model Context Protocol 服务器。该服务器通过标准化接口使 AI 模型能够与 MySQL 数据库进行交互。', '{"meta": null, "serverInfo": {"name": "mysql_mcp_server", "title": null, "version": "1.30.0"}, "capabilities": {"tools": {"listChanged": false}, "logging": null, "prompts": {"listChanged": false}, "resources": {"subscribe": false, "listChanged": false}, "completions": null, "experimental": {}}, "instructions": null, "protocolVersion": "2025-06-18"}', '[{"meta": null, "name": "execute_sql", "title": null, "annotations": {"title": "Execute SQL", "readOnlyHint": false, "openWorldHint": null, "idempotentHint": null, "destructiveHint": true}, "description": "Execute a SQL statement against the MySQL server. Use for SELECT, DML (INSERT/UPDATE/DELETE), SHOW, DESCRIBE, and ad-hoc queries. Supports cross-database queries using database.table notation. Single statements only — use fully qualified names instead of USE statements.", "inputSchema": {"type": "object", "required": ["query"], "properties": {"query": {"type": "string", "description": "The SQL statement to execute. Single statements only."}}}, "outputSchema": null}, {"meta": null, "name": "get_schema_info", "title": null, "annotations": {"title": "Get Schema Info", "readOnlyHint": true, "openWorldHint": null, "idempotentHint": null, "destructiveHint": false}, "description": "Get column metadata for a table or all tables in the configured database: column names, data types, nullability, default values, and comments. Call this before querying an unfamiliar table. Omit table_name to see all tables at once. Accepts bare table names (uses MYSQL_DATABASE) or database.table for cross-database lookups.", "inputSchema": {"type": "object", "properties": {"table_name": {"type": "string", "description": "Optional: bare table name, or database.table for a cross-database lookup."}}}, "outputSchema": null}, {"meta": null, "name": "get_table_sample", "title": null, "annotations": {"title": "Get Table Sample", "readOnlyHint": true, "openWorldHint": null, "idempotentHint": null, "destructiveHint": false}, "description": "Fetch a small sample of rows from a table to understand its data format and content. Use alongside get_schema_info before writing complex queries. Accepts bare table names (uses MYSQL_DATABASE) or database.table for cross-database lookups.", "inputSchema": {"type": "object", "required": ["table_name"], "properties": {"limit": {"type": "integer", "description": "Number of rows to return (default 5, max 20)."}, "table_name": {"type": "string", "description": "Table to sample. Use database.table notation for cross-database queries."}}}, "outputSchema": null}]', '[{"meta": null, "name": "explore_database", "title": null, "arguments": [], "description": "Systematically explore the database: discover available tables, inspect their schemas, sample the data, and summarize what\'s there."}, {"meta": null, "name": "analyze_table", "title": null, "arguments": [{"name": "table_name", "required": true, "description": "Table to analyze. Use database.table notation for cross-database queries."}], "description": "Deep-dive into a specific table: retrieve its schema, sample its data, and suggest useful queries."}]', '[{"uri": "mysql://agent_category/data", "meta": null, "name": "table_agent_category", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: agent_category"}, {"uri": "mysql://agent_chat/data", "meta": null, "name": "table_agent_chat", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: agent_chat"}, {"uri": "mysql://agent_server/data", "meta": null, "name": "table_agent_server", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: agent_server"}, {"uri": "mysql://agent_skill/data", "meta": null, "name": "table_agent_skill", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: agent_skill"}, {"uri": "mysql://alembic_version/data", "meta": null, "name": "table_alembic_version", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: alembic_version"}, {"uri": "mysql://deploy_log/data", "meta": null, "name": "table_deploy_log", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: deploy_log"}, {"uri": "mysql://enterprise/data", "meta": null, "name": "table_enterprise", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: enterprise"}, {"uri": "mysql://mcp_category/data", "meta": null, "name": "table_mcp_category", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: mcp_category"}, {"uri": "mysql://mcp_server/data", "meta": null, "name": "table_mcp_server", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: mcp_server"}, {"uri": "mysql://mcp_user_credential/data", "meta": null, "name": "table_mcp_user_credential", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: mcp_user_credential"}, {"uri": "mysql://skill_category/data", "meta": null, "name": "table_skill_category", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: skill_category"}, {"uri": "mysql://skill_content/data", "meta": null, "name": "table_skill_content", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: skill_content"}, {"uri": "mysql://sys_login_log/data", "meta": null, "name": "table_sys_login_log", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: sys_login_log"}, {"uri": "mysql://sys_menu/data", "meta": null, "name": "table_sys_menu", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: sys_menu"}, {"uri": "mysql://sys_opera_log/data", "meta": null, "name": "table_sys_opera_log", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: sys_opera_log"}, {"uri": "mysql://sys_role/data", "meta": null, "name": "table_sys_role", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: sys_role"}, {"uri": "mysql://sys_role_menu/data", "meta": null, "name": "table_sys_role_menu", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: sys_role_menu"}, {"uri": "mysql://sys_user/data", "meta": null, "name": "table_sys_user", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: sys_user"}, {"uri": "mysql://sys_user_role/data", "meta": null, "name": "table_sys_user_role", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: sys_user_role"}, {"uri": "mysql://sys_user_social/data", "meta": null, "name": "table_sys_user_social", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: sys_user_social"}, {"uri": "mysql://task_result/data", "meta": null, "name": "table_task_result", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: task_result"}, {"uri": "mysql://task_scheduler/data", "meta": null, "name": "table_task_scheduler", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: task_scheduler"}, {"uri": "mysql://task_set_result/data", "meta": null, "name": "table_task_set_result", "size": null, "title": null, "mimeType": "text/plain", "annotations": null, "description": "Data in table: task_set_result"}]', 1, 0, NULL, 1, '2026-11-11 09:21:48', '2026-11-11 09:29:10', NULL);
